use async_trait::async_trait;
use std::path::Path;

/// Abstraction over a workspace backend — the files-and-search sandbox
/// an agent operates in.
///
/// Spec §37: read, write, search, status.  Lived in `harness-runtime` for
/// Phase 1–3; moved into `harness-workspace` in Phase 4.
#[async_trait]
pub trait Workspace: Send + Sync {
    /// Read the full contents of a file at `path`.
    async fn read(&self, path: &Path) -> Result<Vec<u8>, WorkspaceError>;

    /// Write `data` to a file at `path`, creating intermediate directories
    /// as needed.
    async fn write(&self, path: &Path, data: &[u8]) -> Result<(), WorkspaceError>;

    /// Search the workspace according to `query`.
    async fn search(&self, query: SearchQuery) -> Result<SearchResult, WorkspaceError>;

    /// Return a summary of the workspace's current state.
    async fn status(&self) -> Result<WorkspaceStatus, WorkspaceError>;
}

