#[cfg(test)]
mod tests {
    use super::*;
    use tokio::sync::mpsc;

    fn test_descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: harness_protocol::ids::ToolId::new(),
            name: "fake_test_tool".into(),
            description: "A fake tool used in unit tests".into(),
            input_schema: serde_json::json!({}),
        }
    }

    #[tokio::test]
    async fn returns_scripted_ok_outcome() {
        let call_id = ToolCallId::new();
        let expected_output = serde_json::json!({"result": "hello"});
        let outcomes = vec![FakeToolOutcome::ok(call_id, expected_output.clone())];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok result");

        assert_eq!(result.call_id, call_id);
        assert_eq!(result.output, expected_output);
        assert!(!result.is_error);
    }

    #[tokio::test]
    async fn returns_scripted_err_outcome() {
        let outcomes = vec![FakeToolOutcome::err(ToolError::ExecutionFailed)];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let err = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect_err("expected Err");

        assert!(matches!(err, ToolError::ExecutionFailed));
    }

    #[tokio::test]
    async fn returns_error_result_outcome() {
        let call_id = ToolCallId::new();
        let output = serde_json::json!({"error": "file not found"});
        let outcomes = vec![FakeToolOutcome::error_result(call_id, output.clone())];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok result (with is_error flag)");

        assert_eq!(result.call_id, call_id);
        assert_eq!(result.output, output);
        assert!(result.is_error);
    }

    #[tokio::test]
    async fn consumes_outcomes_in_fifo_order() {
        let call_id_a = ToolCallId::new();
        let call_id_b = ToolCallId::new();
        let outcomes = vec![
            FakeToolOutcome::ok(call_id_a, serde_json::json!({"seq": 1})),
            FakeToolOutcome::ok(call_id_b, serde_json::json!({"seq": 2})),
        ];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        // First call → outcome 0
        let r1 = executor
            .execute(context.clone(), serde_json::json!({}), tx.clone(), cancel.clone())
            .await
            .expect("expected Ok on first call");
        assert_eq!(r1.call_id, call_id_a);

        // Second call → outcome 1
        let r2 = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok on second call");
        assert_eq!(r2.call_id, call_id_b);
    }

    #[tokio::test]
    async fn returns_internal_when_script_exhausted() {
        let outcomes = vec![FakeToolOutcome::ok(
            ToolCallId::new(),
            serde_json::json!({"only": "one"}),
        )];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        // First call succeeds
        executor
            .execute(context.clone(), serde_json::json!({}), tx.clone(), cancel.clone())
            .await
            .expect("expected Ok on first call");

        // Second call fails because script is exhausted
        let err = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect_err("expected Err on exhausted script");
        assert!(matches!(err, ToolError::Internal));
    }

    #[tokio::test]
    async fn returns_timeout_on_cancellation() {
        let outcomes = vec![FakeToolOutcome::ok(
            ToolCallId::new(),
            serde_json::json!({"should": "not run"}),
        )];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        cancel.cancel();
        let context = ToolExecutionContext::new();

        let err = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect_err("expected Err on cancelled token");
        assert!(matches!(err, ToolError::Timeout));
    }

    #[tokio::test]
    async fn push_outcome_during_execution() {
        let executor = FakeToolExecutor::with_descriptor(test_descriptor());

        // No outcomes yet — first call should fail.
        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let err = executor
            .execute(context.clone(), serde_json::json!({}), tx.clone(), cancel.clone())
            .await
            .expect_err("expected Err on empty script");
        assert!(matches!(err, ToolError::Internal));

        // Add an outcome and try again.
        let call_id = ToolCallId::new();
        executor.push_outcome(FakeToolOutcome::ok(call_id, serde_json::json!({"late": "ok"})));

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok after push_outcome");
        assert_eq!(result.call_id, call_id);
    }

    #[tokio::test]
    async fn descriptor_trait_and_inherent_methods_agree() {
        let descriptor = test_descriptor();
        let executor = FakeToolExecutor::with_descriptor(descriptor.clone());

        // Call through the inherent method
        let d1 = executor.descriptor();
        // Call through a &dyn ToolExecutor reference (trait dispatch)
        let d2 = <dyn ToolExecutor>::descriptor(&executor);

        assert_eq!(d1.id, descriptor.id);
        assert_eq!(d2.id, descriptor.id);
        assert_eq!(d1.name, d2.name);
    }

    #[tokio::test]
    async fn shared_via_arc_dyn_tool_executor() {
        use std::sync::Arc;

        let descriptor = test_descriptor();
        let outcomes = vec![FakeToolOutcome::ok(
            ToolCallId::new(),
            serde_json::json!({"via": "arc"}),
        )];
        let executor: Arc<dyn ToolExecutor> =
            Arc::new(FakeToolExecutor::new(descriptor, outcomes));

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok via Arc<dyn ToolExecutor>");
        assert_eq!(result.output, serde_json::json!({"via": "arc"}));
    }
}

