    /// Multiple commands should be processed sequentially.
    #[tokio::test]
    async fn multiple_commands_processed() {
        let backend = Arc::new(FakeBackend::new(vec![], Ok(ExecutionResult {
            request_id: harness_protocol::ids::RequestId::new(),
            usage: harness_protocol::usage::ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: "end_turn".into(),
        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(dummy_agent(), task, backend, cmd_tx.clone());

        // Send StartRun
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "first".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Send Pause
        cmd_tx
            .send(AgentCommand::Pause)
            .await
            .expect("send Pause");

        // Cancel to finish the run so the runner releases its command sender.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        runner.run().await;

        // We should have received at least one event.
        let mut count = 0;
        while let Ok(_) = evt_rx.try_recv() {
            count += 1;
        }
        assert!(count > 0, "expected at least one event");
    }

    /// Given a [`FakeBackend`] scripted to emit a text delta then complete,
    /// running the loop from `StartRun` to completion produces the expected
    /// ordered event stream on the broadcast channel: a `RunStarted` event,
    /// an `AssistantTextDelta` with the scripted text, and a `Completed`
    /// (success) event.
    #[tokio::test]
    async fn execute_backend_feeds_events_back() {
        use harness_protocol::ids::RequestId;
        use harness_protocol::usage::{Cost, ModelUsage};

        let request_id = RequestId::new();
        let expected_delta = "Hello ".to_string();

        let scripted_events = vec![
            ExecutionEvent::TextDelta {
                request_id,
                delta: expected_delta.clone(),
            },
            ExecutionEvent::Completed {
                request_id,
                result: ExecutionResult {
                    request_id,
                    usage: ModelUsage::default(),
                    cost: Cost::default(),
                    finish_reason: "end_turn".into(),
                },
            },
        ];

        let backend = Arc::new(FakeBackend::new(
            scripted_events,
            Ok(ExecutionResult {
                request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            }),
        ));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(dummy_agent(), task, backend, cmd_tx.clone());

        // Send StartRun — this triggers ExecuteBackend which will dispatch
        // to the FakeBackend and feed events back.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "test".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Drop the external sender.  When the run finishes (via the
        // Completed event → FinishRun), the runner will also drop its
        // internal sender, and the channel will close.
        drop(cmd_tx);

        // Run the event loop until the backend finishes and the agent
        // completes the run.
        runner.run().await;

        // Collect all broadcast events in order.
        let mut events: Vec<AgentEvent> = Vec::new();
        while let Ok(envelope) = evt_rx.try_recv() {
            events.push(envelope.event);
        }

        // Verify the critical events appear in the correct order.
        //
        // Expected sequence (modulo StateChanged events which we skip for
        // brevity):
        //   0. StateChanged(Idle → PreparingContext)
        //   1. RunStarted { run_id }
        //   2. StateChanged(PreparingContext → Streaming)
        //   3. AssistantTextDelta { delta: "Hello " }
        //   4. StateChanged(Streaming → Idle)
        //   5. Completed { outcome: Success }

        // Locate the key events by index and verify order.
        let run_started_idx = events
            .iter()
            .position(|e| matches!(e, AgentEvent::RunStarted { .. }))
            .expect("RunStarted should be emitted");

        let text_delta_idx = events
            .iter()
            .position(|e| {
                matches!(e, AgentEvent::AssistantTextDelta { delta, .. } if delta == &expected_delta)
            })
            .expect("AssistantTextDelta should be emitted with the correct delta");

        let completed_idx = events
            .iter()
            .position(|e| matches!(e, AgentEvent::Completed { .. }))
            .expect("Completed should be emitted");

        // Verify ordering: RunStarted → AssistantTextDelta → Completed
        assert!(
            run_started_idx < text_delta_idx,
            "RunStarted should appear before AssistantTextDelta"
        );
        assert!(
            text_delta_idx < completed_idx,
            "AssistantTextDelta should appear before Completed"
        );

        // Verify the run result is set by the FinishRun effect.
        let result = runner
            .last_result()
            .expect("FinishRun should set last_result");
        assert!(!result.summary.is_empty(), "result summary should not be empty");
    }
}

