    };
    use harness_protocol::commands::{AgentCommand, UserInput};
    use harness_protocol::events::AgentEvent;
    use harness_protocol::ids::{
        AgentId, BackendId, ConfigurationId, IntegrationId, SessionId, ToolCallId, ToolId,
    };
    use harness_protocol::tools::{
        AgentToolset, PermissionMode, ToolCall, ToolDescriptor, ToolError, ToolPolicy,
        ToolCapability,
    };

    use crate::agent_runner::{AgentRunner, AgentTask};
    use crate::testing::fake_backend::FakeBackend;
    use crate::testing::fake_tools::{FakeToolExecutor, FakeToolOutcome};
    use crate::traits::ToolRegistry;

    fn dummy_agent() -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
