    }

    /// Sending a [`StartRun`] then [`Cancel`] produces a [`RunStarted`] event
    /// on the broadcast channel with correct session/agent metadata, and
    /// eventually a [`FinishRun`] result.
    #[tokio::test]
    async fn emit_effect_forwards_event() {
        let backend = Arc::new(FakeBackend::new(vec![], Ok(ExecutionResult {
            request_id: harness_protocol::ids::RequestId::new(),
            usage: harness_protocol::usage::ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: "end_turn".into(),
        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            dummy_agent(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );
        let agent_id = runner.agent().id;
        let session_id = runner.agent().session_id;

        // Send a StartRun command (which triggers at least one Emit effect)
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "hello".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Send Cancel to end the run.  Cancel does not emit FinishRun,
        // but the runner detects `active_run == None` after processing
        // the Cancel effects and releases its command sender.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        // Drop the external sender so the channel can close.
        drop(cmd_tx);

        // Run the event loop.
        runner.run().await;

        // Verify we received at least one event envelope.
        let envelope = evt_rx.try_recv().expect("should have received an event");
        assert_eq!(envelope.agent_id, agent_id);
        assert_eq!(envelope.session_id, session_id);

        // The first event from StartRun is a RunStarted.
        match envelope.event {
            AgentEvent::RunStarted { .. } => {} // expected
            ref other => panic!("expected RunStarted, got {other:?}"),
        }
    }

    /// A `FinishRun` effect should be recorded as the runner's last result.
    #[tokio::test]
    async fn finish_run_records_result() {
        let backend = Arc::new(FakeBackend::new(vec![], Ok(ExecutionResult {
            request_id: harness_protocol::ids::RequestId::new(),
            usage: harness_protocol::usage::ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: "end_turn".into(),
        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            dummy_agent(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );

        // Send StartRun then Cancel — Cancel triggers FinishRun.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "cancel me".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        runner.run().await;

        // After Cancel, the agent should have recorded a FinishRun result
        let result = runner
            .last_result()
            .expect("FinishRun should set last_result");
        // A cancellation produces a non-empty summary like "Run completed: cancelled"
        // (The actual content depends on the Cancel transition logic.)
        assert!(
            !result.summary.is_empty(),
            "cancellation summary should not be empty"
        );
    }

    /// Cancellation token should cause the runner to exit promptly even
    /// when no commands are sent.
    #[tokio::test]
    async fn cancel_token_exits_loop() {
        let backend = Arc::new(FakeBackend::new(vec![], Ok(ExecutionResult {
            request_id: harness_protocol::ids::RequestId::new(),
            usage: harness_protocol::usage::ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: "end_turn".into(),
        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(dummy_agent(), task, backend, tool_registry, cmd_tx);

        // Spawn the runner and cancel immediately
        let handle = tokio::spawn(async move {
            runner.run().await;
        });

        cancel.cancel();
        let _ = handle.await;
    }

    /// Multiple commands should be processed sequentially.
    #[tokio::test]
    async fn multiple_commands_processed() {
        let backend = Arc::new(FakeBackend::new(vec![], Ok(ExecutionResult {
            request_id: harness_protocol::ids::RequestId::new(),
            usage: harness_protocol::usage::ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: "end_turn".into(),
        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            dummy_agent(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );

        // Send StartRun
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "first".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Send Pause
        cmd_tx
            .send(AgentCommand::Pause)
            .await
            .expect("send Pause");

        // Cancel to finish the run so the runner releases its command sender.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        runner.run().await;

        // We should have received at least one event.
        let mut count = 0;
        while let Ok(_) = evt_rx.try_recv() {
            count += 1;
        }
        assert!(count > 0, "expected at least one event");
    }

    /// Given a [`FakeBackend`] scripted to emit a text delta then complete,
    /// running the loop from `StartRun` to completion produces the expected
    /// ordered event stream on the broadcast channel: a `RunStarted` event,
    /// an `AssistantTextDelta` with the scripted text, and a `Completed`
    /// (success) event.
    #[tokio::test]
    async fn execute_backend_feeds_events_back() {
        use harness_protocol::ids::RequestId;
        use harness_protocol::usage::{Cost, ModelUsage};

        let request_id = RequestId::new();
        let expected_delta = "Hello ".to_string();

        let scripted_events = vec![
            ExecutionEvent::TextDelta {
                request_id,
                delta: expected_delta.clone(),
            },
            ExecutionEvent::Completed {
                request_id,
                result: ExecutionResult {
                    request_id,
                    usage: ModelUsage::default(),
                    cost: Cost::default(),
                    finish_reason: "end_turn".into(),
                },
            },
        ];

        let backend = Arc::new(FakeBackend::new(
            scripted_events,
            Ok(ExecutionResult {
                request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            }),
        ));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            dummy_agent(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );

        // Send StartRun — this triggers ExecuteBackend which will dispatch
        // to the FakeBackend and feed events back.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "test".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Drop the external sender.  When the run finishes (via the
        // Completed event → FinishRun), the runner will also drop its
        // internal sender, and the channel will close.
        drop(cmd_tx);

        // Run the event loop until the backend finishes and the agent
        // completes the run.
        runner.run().await;

        // Collect all broadcast events in order.
        let mut events: Vec<AgentEvent> = Vec::new();
        while let Ok(envelope) = evt_rx.try_recv() {
            events.push(envelope.event);
        }

        // Verify the critical events appear in the correct order.
        //
        // Expected sequence (modulo StateChanged events which we skip for
        // brevity):
        //   0. StateChanged(Idle → PreparingContext)
        //   1. RunStarted { run_id }
        //   2. StateChanged(PreparingContext → Streaming)
        //   3. AssistantTextDelta { delta: "Hello " }
        //   4. StateChanged(Streaming → Idle)
        //   5. Completed { outcome: Success }

        // Locate the key events by index and verify order.
        let run_started_idx = events
            .iter()
            .position(|e| matches!(e, AgentEvent::RunStarted { .. }))
            .expect("RunStarted should be emitted");

        let text_delta_idx = events
            .iter()
            .position(|e| {
                matches!(e, AgentEvent::AssistantTextDelta { delta, .. } if delta == &expected_delta)
            })
            .expect("AssistantTextDelta should be emitted with the correct delta");

        let completed_idx = events
            .iter()
            .position(|e| matches!(e, AgentEvent::Completed { .. }))
            .expect("Completed should be emitted");

        // Verify ordering: RunStarted → AssistantTextDelta → Completed
        assert!(
            run_started_idx < text_delta_idx,
            "RunStarted should appear before AssistantTextDelta"
        );
        assert!(
            text_delta_idx < completed_idx,
            "AssistantTextDelta should appear before Completed"
        );

        // Verify the run result is set by the FinishRun effect.
        let result = runner
            .last_result()
            .expect("FinishRun should set last_result");
        assert!(!result.summary.is_empty(), "result summary should not be empty");
    }

    /// When the agent emits an [`AgentEffect::ExecuteTool`] for a tool that
    /// is registered in the [`ToolRegistry`], the runner dispatches it and
