        // A cancellation produces a non-empty summary
        assert!(!result.summary.is_empty(), "cancellation summary should not be empty");
    }

    /// Cancellation token should cause the runner to exit promptly even
    /// when no commands are sent.
    #[tokio::test]
    async fn cancel_token_exits_loop() {
        let (_cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(dummy_agent(), task);

        // Spawn the runner and cancel immediately
        let handle = tokio::spawn(async move {
            runner.run().await;
        });

        cancel.cancel();
        let _ = handle.await;
    }

    /// Multiple commands should be processed sequentially.
    #[tokio::test]
    async fn multiple_commands_processed() {
        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(dummy_agent(), task);

        // Send StartRun
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "first".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Send Pause
        cmd_tx
            .send(AgentCommand::Pause)
            .await
            .expect("send Pause");

        drop(cmd_tx);

        runner.run().await;

        // We should have received at least one event
        let mut count = 0;
        while let Ok(_) = evt_rx.try_recv() {
            count += 1;
        }
        assert!(count > 0, "expected at least one event");
    }

    /// When the agent enters `WaitingForPermission` (tool with `Ask` mode),
    /// the runner blocks until a matching `PermissionResolved` arrives.
    ///
    /// This test drives the full cycle:
    ///   StartRun → BackendEvent(ToolCallRequested) → PermissionResolved → Cancel
    #[tokio::test]
    async fn request_permission_awaits_resolution() {
        let (cmd_tx, cmd_rx) = mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        // Subscribe to the event bus BEFORE the sender is moved into the runner.
        let mut event_sub = evt_tx.subscribe();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(agent_with_ask_tool(), task);

        // Send StartRun to kick off a run
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "read a file".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Spawn the runner in a background task so we can interact with
        // it while it's blocked waiting for permission.
        let (result_tx, mut result_rx) = mpsc::channel(1);
        let handle = tokio::spawn(async move {
            runner.run().await;
            let _ = result_tx.send(runner).await;
        });

        // Read events until we get RunStarted (to learn the run_id).
        let run_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::RunStarted { run_id } = envelope.event {
                        break run_id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Trigger a tool call request to put the agent in WaitingForPermission.
        let call = ToolCall {
            id: ToolCallId::new(),
            name: "test.read".into(),
            arguments: serde_json::json!({"path": "/tmp/test.txt"}),
        };
        cmd_tx
            .send(AgentCommand::BackendEvent {
                run_id,
                event: ExecutionEvent::ToolCallRequested {
                    request_id: RequestId::new(),
                    call,
                },
            })
            .await
            .expect("send ToolCallRequested");

        // Read the PermissionRequested event to get the permission ID.
        let permission_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::PermissionRequested { ref request } = envelope.event {
                        break request.id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Resolve the permission (approve it).
        cmd_tx
            .send(AgentCommand::PermissionResolved {
                id: permission_id,
                decision: PermissionDecision::Approved,
            })
            .await
            .expect("send PermissionResolved");

        // Clean up by cancelling the run.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        // Wait for the runner to finish and retrieve it.
        let _ = handle.await;
        let runner = result_rx
            .recv()
            .await
            .expect("runner should complete and be sent back");

        assert!(
            runner.last_result().is_some(),
            "expected a finish result after permission resolution"
        );
    }

    /// A `PermissionResolved` with a non-matching ID should be ignored
    /// by the runner (it stays in the wait loop).
    #[tokio::test]
    async fn permission_resolved_wrong_id_ignored() {
        let (cmd_tx, cmd_rx) = mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let mut event_sub = evt_tx.subscribe();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(agent_with_ask_tool(), task);

        // Send StartRun.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "read a file".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        let (result_tx, mut result_rx) = mpsc::channel(1);
        let handle = tokio::spawn(async move {
            runner.run().await;
            let _ = result_tx.send(runner).await;
        });

        // Get run_id from RunStarted.
        let run_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::RunStarted { run_id } = envelope.event {
                        break run_id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Trigger tool call to enter WaitingForPermission.
        let call = ToolCall {
            id: ToolCallId::new(),
            name: "test.read".into(),
            arguments: serde_json::json!({"path": "/tmp/test.txt"}),
        };
        cmd_tx
            .send(AgentCommand::BackendEvent {
                run_id,
                event: ExecutionEvent::ToolCallRequested {
                    request_id: RequestId::new(),
                    call,
                },
            })
            .await
            .expect("send ToolCallRequested");

        // Read the real permission_id.
        let real_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::PermissionRequested { ref request } = envelope.event {
                        break request.id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Send a PermissionResolved with a WRONG ID — should not match
        // and the runner stays in the wait loop.
        let wrong_id = PermissionId::new();
        cmd_tx
            .send(AgentCommand::PermissionResolved {
                id: wrong_id,
                decision: PermissionDecision::Approved,
            })
            .await
            .expect("send wrong PermissionResolved");

        // Now send the CORRECT ID — this should resolve the wait.
        cmd_tx
            .send(AgentCommand::PermissionResolved {
                id: real_id,
                decision: PermissionDecision::Approved,
            })
            .await
            .expect("send correct PermissionResolved");

        // Clean up.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        let _ = handle.await;
        let runner = result_rx
            .recv()
            .await
            .expect("runner should complete");

        assert!(
            runner.last_result().is_some(),
            "expected a finish result"
        );
    }

    /// Cancelling while waiting for permission should work (Cancel is
    /// forwarded to the agent during the wait).
    #[tokio::test]
    async fn cancel_while_waiting_for_permission() {
        let (cmd_tx, cmd_rx) = mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let mut event_sub = evt_tx.subscribe();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(agent_with_ask_tool(), task);

        // Send StartRun.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "read a file".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        let (result_tx, mut result_rx) = mpsc::channel(1);
        let handle = tokio::spawn(async move {
            runner.run().await;
            let _ = result_tx.send(runner).await;
        });

        // Get run_id from RunStarted.
        let run_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::RunStarted { run_id } = envelope.event {
                        break run_id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Trigger tool call to enter WaitingForPermission.
        let call = ToolCall {
            id: ToolCallId::new(),
            name: "test.read".into(),
            arguments: serde_json::json!({"path": "/tmp/test.txt"}),
        };
        cmd_tx
            .send(AgentCommand::BackendEvent {
                run_id,
                event: ExecutionEvent::ToolCallRequested {
                    request_id: RequestId::new(),
                    call,
                },
            })
            .await
            .expect("send ToolCallRequested");

        // Cancel while the agent is waiting for permission.
        // The runner's nested loop will forward Cancel to the agent,
        // which transitions to Cancelled and produces FinishRun.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        let _ = handle.await;
        let runner = result_rx
            .recv()
            .await
            .expect("runner should complete");

        let result = runner
            .last_result()
            .expect("should have finished after cancel");
        assert!(
            !result.summary.is_empty(),
            "cancellation should produce a summary"
        );
    }

    /// The `Persist` effect should not crash or block — it is a silent
    /// no-op in Phase 2.
    #[tokio::test]
    async fn persist_effect_is_noop() {
        let (cmd_tx, cmd_rx) = mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let mut runner = AgentRunner::new(dummy_agent(), task);

        // Start a run — the Persist effect is not directly triggered
        // by the agent transition logic in Phase 1/2, but we verify
        // that the match arm compiles and runs without error.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "hello".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        runner.run().await;

        // Just ensure we got a result — the Persist arm was never hit
        // but the code compiles.
        assert!(runner.last_result().is_some());
    }
}

