                    name: "nonexistent_tool".into(),
                    description: "A tool that has no executor".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: false,
            },
        );

        let agent = Agent::new(
            AgentId::new(),
            SessionId::new(),
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "fake".into(),
                    description: "fake".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset { tools },
                can_spawn_agents: false,
                max_child_depth: None,
                workspace: WorkspaceCapabilities {
                    can_read: false,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        let mut runner = AgentRunner::new(agent, task, backend, tool_registry, cmd_tx.clone());

        // Send StartRun — the backend will emit ToolCallRequested for
        // "nonexistent_tool", the agent will emit ExecuteTool, and the
        // runner should reply with ToolFailed since the tool isn't in
        // the registry.
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "use nonexistent tool".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        drop(cmd_tx);

        runner.run().await;

        // The run should still complete (the agent handles ToolFailed
        // gracefully and eventually the Completed event from the backend
        // terminates the run).
        let mut events: Vec<AgentEvent> = Vec::new();
        while let Ok(envelope) = evt_rx.try_recv() {
            events.push(envelope.event);
        }

        assert!(
            events.iter().any(|e| matches!(e, AgentEvent::Completed { .. })),
            "expected Completed event even with unknown tool"
        );

        let result = runner
            .last_result()
            .expect("FinishRun should set last_result");
        assert!(!result.summary.is_empty(), "result summary should not be empty");
    }
}

