        match snap.current_operation.unwrap() {
            AgentOperation::Tools { calls } => {
                assert_eq!(calls.len(), 1);
            }
            other => panic!("expected Tools, got {other:?}"),
        }
    }

    // -----------------------------------------------------------------------
    // SessionSnapshot construction
    // -----------------------------------------------------------------------

    /// A `SessionSnapshot` can be constructed from raw parts.
    #[test]
    fn session_snapshot_from_parts() {
        let id = SessionId::new();
        let root_agent_id = AgentId::new();

        let snap = SessionSnapshot::new(
            id,
            SessionStatus::Running,
            root_agent_id,
            vec![],
            SessionUsageSnapshot {
                session_id: id.to_string(),
                cumulative: CumulativeUsage {
                    total_tokens: UsageValue::new(None),
                    total_cost: None,
                    total_requests: 0,
                },
                timestamp: String::new(),
            },
        );

        assert_eq!(snap.id, id);
        assert_eq!(snap.status, SessionStatus::Running);
        assert_eq!(snap.root_agent_id, root_agent_id);
        assert!(snap.agents.is_empty());
        assert_eq!(snap.usage.session_id, id.to_string());
    }

    /// A `SessionSnapshot` can be constructed with agent snapshots.
    #[test]
    fn session_snapshot_with_agents() {
        let id = SessionId::new();
        let root_agent_id = AgentId::new();

        let agent = Agent::new(
            root_agent_id,
            id,
            None,
            "system".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "test".into(),
                    description: "".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: HashMap::new(),
                },
                can_spawn_agents: false,
                max_child_depth: None,
                workspace: WorkspaceCapabilities {
                    can_read: false,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        let agent_snap = AgentSnapshot::from_agent(&agent);

        let snap = SessionSnapshot::from_parts(
            id,
            SessionStatus::Running,
            root_agent_id,
            vec![agent_snap],
            SessionUsageSnapshot::default(),
        );

        assert_eq!(snap.agents.len(), 1);
        assert_eq!(snap.agents[0].id, root_agent_id);
    }
}

