//! Session builder, handle, and runtime types for the public Harness API.
//!
//! This module provides the ergonomic builder chain:
//!
//! ```rust,ignore
//! let session = harness
//!     .session()
//!     .backend(backend)
//!     .tools(toolset)
//!     .start()
//!     .await?;
//! ```
//!
//! Internally it creates a [`LocalSessionClient`] that owns an in-process
//! agent runtime loop, dispatching commands to the agent state machine and
//! forwarding emitted events to subscribers.

use std::sync::Arc;

use async_trait::async_trait;
use tokio::sync::{broadcast, mpsc};

use harness_core::agent::Agent;
use harness_core::capabilities::{AgentCapabilities, WorkspaceCapabilities};
use harness_protocol::backend::{
    BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference, ExecutionError,
    ExecutionEvent, ExecutionRequest, ExecutionResult,
};
use harness_protocol::commands::{AgentCommand, UserInput};
use harness_protocol::effects::AgentEffect;
use harness_protocol::events::{AgentEvent, AgentEventEnvelope, EventVisibility};
use harness_protocol::ids::{
    AgentId, ConfigurationId, EventId, IntegrationId, PermissionId, RunId, SessionId, Timestamp,
};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::{AgentBudget, CumulativeUsage, SessionUsageSnapshot};

// ---------------------------------------------------------------------------
// ExecutionBackend trait
// ---------------------------------------------------------------------------

/// A backend that can execute model requests.
///
/// Defined here temporarily until `harness-runtime` provides it (see spec §11.1, §76).
/// Each call to [`execute`](ExecutionBackend::execute) streams [`ExecutionEvent`]s
/// through the provided `mpsc::Sender` and returns the final [`ExecutionResult`].
#[async_trait]
pub trait ExecutionBackend: Send + Sync {
    /// Static descriptor (identity + capabilities).
    fn descriptor(&self) -> BackendDescriptor;

    /// Cached capabilities (should match `descriptor().capabilities`).
    fn capabilities(&self) -> BackendCapabilities;

    /// Execute a request, streaming events through `events_tx`.
    ///
    /// The implementation should:
    /// 1. Send streaming events (e.g. [`ExecutionEvent::TextDelta`]) through `events_tx`.
    /// 2. Send a terminal event ([`ExecutionEvent::Completed`] or [`ExecutionEvent::Error`])
    ///    through `events_tx` after all streaming events are done.
    /// 3. Close the `events_tx` channel and return the final [`ExecutionResult`].
    async fn execute(
        &self,
        request: ExecutionRequest,
        events_tx: mpsc::Sender<ExecutionEvent>,
    ) -> Result<ExecutionResult, ExecutionError>;
}

// ---------------------------------------------------------------------------
// SessionCommand — user-facing commands (spec §48)
// ---------------------------------------------------------------------------

/// Commands a user may send to a session.
#[derive(Debug, Clone)]
pub enum SessionCommand {
    /// Send a user prompt to start / continue a run.
    Prompt(UserInput),
    /// Cancel the active run.
    CancelRun { run_id: RunId },
    /// Cancel a specific agent.
    CancelAgent { agent_id: AgentId },
    /// Pause an agent.
    PauseAgent { agent_id: AgentId },
    /// Resume a paused agent.
    ResumeAgent { agent_id: AgentId },
    /// Approve a pending permission request.
    ApprovePermission { id: PermissionId },
    /// Reject a pending permission request.
    RejectPermission { id: PermissionId },
}

// ---------------------------------------------------------------------------
// SessionStatus
// ---------------------------------------------------------------------------

/// High-level session status.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SessionStatus {
    /// Session is active and accepting commands.
    Active,
    /// Session has completed successfully.
    Completed,
    /// Session failed with an error.
    Failed,
}

// ---------------------------------------------------------------------------
// SessionSnapshot — point-in-time state (spec §45)
// ---------------------------------------------------------------------------

/// A point-in-time view of session state.
#[derive(Debug, Clone)]
pub struct SessionSnapshot {
    /// The session ID.
    pub id: SessionId,
    /// Current session status.
    pub status: SessionStatus,
    /// The root agent's ID.
    pub root_agent_id: AgentId,
    /// Cumulative usage snapshot.
    pub usage: SessionUsageSnapshot,
}

// ---------------------------------------------------------------------------
// SessionEvent — events emitted by a session (spec §44)
// ---------------------------------------------------------------------------

/// Events emitted by a session to subscribers.
#[derive(Debug, Clone)]
pub enum SessionEvent {
    /// The session has started.
    SessionStarted,
    /// Session status changed.
    StatusChanged { status: SessionStatus },
    /// An event from an agent in this session.
    Agent { event: AgentEventEnvelope },
    /// An agent was added to the session.
    AgentAdded { agent: AgentId },
    /// An agent was removed from the session.
    AgentRemoved { agent_id: AgentId },
    /// Usage snapshot update.
    UsageUpdated { usage: SessionUsageSnapshot },
    /// Session completed successfully.
    Completed,
    /// Session failed with an error.
    Failed { error: String },
}

/// A stream of [`SessionEvent`]s obtained from [`SessionClient::subscribe`].
pub type SessionEventStream = broadcast::Receiver<SessionEvent>;

// ---------------------------------------------------------------------------
// SessionError
// ---------------------------------------------------------------------------

/// Errors that can occur during session operations.
#[derive(Debug, thiserror::Error)]
pub enum SessionError {
    /// The session has already completed.
    #[error("Session already completed")]
    AlreadyCompleted,
    /// No active run to cancel.
    #[error("No active run to cancel")]
    NoActiveRun,
    /// Agent not found.
    #[error("Agent not found: {0}")]
    AgentNotFound(AgentId),
    /// Internal session error.
    #[error("Internal error: {0}")]
    Internal(String),
    /// Backend execution error.
    #[error("Backend error: {0}")]
    Backend(String),
    /// The command channel was closed (session terminated).
    #[error("Session command channel closed")]
    ChannelClosed,
}

// ---------------------------------------------------------------------------
// SessionClient trait (spec §48, §76)
// ---------------------------------------------------------------------------

/// Public session API that frontends use to interact with a session.
///
/// This is the primary interface that both [`LocalSessionClient`] and future
/// `RemoteSessionClient` implement, enabling transport transparency.
#[async_trait]
pub trait SessionClient: Send + Sync {
    /// Send a command to the session.
    async fn send(&self, command: SessionCommand) -> Result<(), SessionError>;

    /// Subscribe to the session's event stream.
    fn subscribe(&self) -> SessionEventStream;

    /// Get a point-in-time snapshot of session state.
    async fn snapshot(&self) -> Result<SessionSnapshot, SessionError>;
}

// ---------------------------------------------------------------------------
// SessionHandle — public opaque handle wrapping a SessionClient
// ---------------------------------------------------------------------------

/// An opaque handle to an active session (spec §63, §76).
///
/// Wraps an `Arc<dyn SessionClient>` so frontends never depend on the concrete
/// local or remote implementation.  This is the primary type that application
/// code uses to interact with a running session.
#[derive(Clone)]
pub struct SessionHandle {
    client: Arc<dyn SessionClient>,
}

impl SessionHandle {
    /// Wrap a [`SessionClient`] into a handle.
    pub fn new(client: Arc<dyn SessionClient>) -> Self {
        Self { client }
    }

    /// Send a command to the session.
    pub async fn send(&self, command: SessionCommand) -> Result<(), SessionError> {
        self.client.send(command).await
    }

    /// Subscribe to the session's event stream.
    pub fn subscribe(&self) -> SessionEventStream {
        self.client.subscribe()
    }

    /// Get a point-in-time snapshot of the session.
    pub async fn snapshot(&self) -> Result<SessionSnapshot, SessionError> {
        self.client.snapshot().await
    }
}

// ---------------------------------------------------------------------------
// Internal message types for the agent runner
// ---------------------------------------------------------------------------

/// Internal messages sent to the background agent loop.
enum InternalMessage {
    /// A user-facing session command.
    Command(SessionCommand),
}

// ---------------------------------------------------------------------------
// LocalSessionClient — in-process session implementation
// ---------------------------------------------------------------------------

/// An in-process [`SessionClient`] that runs the agent loop directly.
///
/// Owns an [`Agent`] state machine and dispatches commands/backend events
/// through internal channels.  All agent transitions happen synchronously
/// on the background task; I/O (backend calls) is spawned as child tasks.
pub struct LocalSessionClient {
    /// Sender for commands flowing to the background agent loop.
    command_tx: mpsc::Sender<InternalMessage>,
    /// Broadcast sender for session events (cloned for each subscriber).
    event_tx: broadcast::Sender<SessionEvent>,
    /// Shared snapshot protected by a mutex.
    snapshot: Arc<std::sync::Mutex<SessionSnapshot>>,
}

impl LocalSessionClient {
    /// Create a new local session with the given backend and toolset.
    ///
    /// Spawns a background tokio task that owns the agent state machine and
    /// processes commands and backend events.
    pub fn new(
        backend: Arc<dyn ExecutionBackend>,
        tools: AgentToolset,
    ) -> Self {
        let session_id = SessionId::new();
        let root_agent_id = AgentId::new();

        let (command_tx, command_rx) = mpsc::channel::<InternalMessage>(64);
        let (event_tx, _event_rx) = broadcast::channel::<SessionEvent>(256);

        let snapshot = Arc::new(std::sync::Mutex::new(SessionSnapshot {
            id: session_id,
            status: SessionStatus::Active,
            root_agent_id,
            usage: SessionUsageSnapshot {
                session_id: session_id.to_string(),
                cumulative: CumulativeUsage::default(),
                timestamp: String::new(),
            },
        }));

        let snapshot_clone = snapshot.clone();
        let event_tx_clone = event_tx.clone();

        // Spawn the background agent runner loop
        tokio::spawn(async move {
            run_agent_loop(
                session_id,
                root_agent_id,
                backend,
                tools,
                command_rx,
                event_tx_clone,
                snapshot_clone,
            )
            .await;
        });

        Self {
            command_tx,
            event_tx,
            snapshot,
        }
    }
}

#[async_trait]
impl SessionClient for LocalSessionClient {
    async fn send(&self, command: SessionCommand) -> Result<(), SessionError> {
        self.command_tx
            .send(InternalMessage::Command(command))
            .await
            .map_err(|_| SessionError::ChannelClosed)
    }

    fn subscribe(&self) -> SessionEventStream {
        self.event_tx.subscribe()
    }

    async fn snapshot(&self) -> Result<SessionSnapshot, SessionError> {
        let snap = self
            .snapshot
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        Ok(snap.clone())
    }
}

// ---------------------------------------------------------------------------
// Agent runner loop
// ---------------------------------------------------------------------------

/// Run the background agent loop.
///
/// Owns the [`Agent`] state machine.  Receives commands via `command_rx`,
/// processes them by calling `agent.apply(...)`, interprets the resulting
/// [`AgentEffect`]s by dispatching to the backend or emitting events.
#[allow(clippy::too_many_arguments)]
async fn run_agent_loop(
    session_id: SessionId,
    agent_id: AgentId,
    backend: Arc<dyn ExecutionBackend>,
    tools: AgentToolset,
    mut command_rx: mpsc::Receiver<InternalMessage>,
    event_tx: broadcast::Sender<SessionEvent>,
    snapshot: Arc<std::sync::Mutex<SessionSnapshot>>,
) {
    // Build the root agent
    let backend_desc = backend.descriptor();
    let agent = Agent::new(
        agent_id,
        session_id,
        None,
        String::new(),
        BackendBinding {
            reference: BackendReference {
                integration: IntegrationId::new(),
                configuration: ConfigurationId::new(),
                model: None,
            },
            descriptor: backend_desc.clone(),
        },
        AgentCapabilities {
            tools,
            can_spawn_agents: false,
            max_child_depth: None,
            workspace: WorkspaceCapabilities {
                can_read: false,
                can_write: false,
                can_search: false,
            },
            backend: backend_desc.capabilities,
        },
        AgentBudget::default(),
    );

    let agent = std::sync::Mutex::new(agent);

    // Emit SessionStarted
    let _ = event_tx.send(SessionEvent::SessionStarted);

    while let Some(msg) = command_rx.recv().await {
        match msg {
            InternalMessage::Command(SessionCommand::Prompt(input)) => {
                let effects = {
                    let mut guard = agent.lock().unwrap();
                    guard.apply(AgentCommand::StartRun { input })
                };
                process_effects(&agent, &backend, &event_tx, &snapshot, effects).await;
            }
            InternalMessage::Command(SessionCommand::CancelRun { .. }) => {
                let effects = {
                    let mut guard = agent.lock().unwrap();
                    guard.apply(AgentCommand::Cancel)
                };
                process_effects(&agent, &backend, &event_tx, &snapshot, effects).await;
            }
            InternalMessage::Command(SessionCommand::CancelAgent { .. })
            | InternalMessage::Command(SessionCommand::PauseAgent { .. })
            | InternalMessage::Command(SessionCommand::ResumeAgent { .. })
            | InternalMessage::Command(SessionCommand::ApprovePermission { .. })
            | InternalMessage::Command(SessionCommand::RejectPermission { .. }) => {
                // Stub — not yet implemented for this phase
            }
        }
    }
}

/// Process effects produced by an agent transition.
///
/// This is the core runtime-dispatch loop (spec §10 / §32).
///
/// Effects are processed in two phases within each batch to maintain correct
/// ordering:
///
/// 1. **Side-effect phase** — `Emit` and `FinishRun` are dispatched
///    immediately. These must appear *before* any blocking I/O so that
///    notifications (e.g. `RunStarted`) are visible to subscribers before
///    the backend starts streaming.
///
/// 2. **Blocking phase** — `ExecuteBackend` is spawned as a background task;
///    its streamed events are collected, fed back into the agent state
///    machine, and the resulting effects are recursively processed.
///
/// | Effect | Phase | Action |
/// |---|---|---|
/// | `Emit` | 1 | Wrap in [`AgentEventEnvelope`], broadcast as [`SessionEvent::Agent`] |
/// | `FinishRun` | 1 | Broadcast [`SessionEvent::Completed`], update snapshot |
/// | `ExecuteBackend` | 2 | Spawn backend, collect events, feed to agent, recurse |
/// | Others | — | Stubbed (tool execution, spawn, permission, etc. — Phase 3+) |
async fn process_effects(
    agent: &std::sync::Mutex<Agent>,
    backend: &Arc<dyn ExecutionBackend>,
    event_tx: &broadcast::Sender<SessionEvent>,
    snapshot: &Arc<std::sync::Mutex<SessionSnapshot>>,
    effects: Vec<AgentEffect>,
) {
    // ── Phase 1: side-effects (emits & finish) — these must appear before
    //    any blocking backend I/O in the same batch so that subscribers see
    //    notifications (e.g. RunStarted) before streaming begins.

    let mut backend_requests: Vec<ExecutionRequest> = Vec::new();

    for effect in &effects {
        match effect {
            AgentEffect::Emit { event } => {
                let event = event.clone();
                let envelope = {
                    let guard = agent.lock().unwrap();
                    let seq = guard.state.transition_sequence;
                    AgentEventEnvelope {
                        event_id: EventId::new(),
                        session_id: guard.session_id,
                        agent_id: guard.id,
                        parent_agent_id: guard.parent_id,
                        run_id: guard.state.active_run,
                        agent_sequence: seq,
                        session_sequence: Some(seq),
                        timestamp: Timestamp::now(),
                        visibility: EventVisibility::User,
                        event,
                    }
                };
                let _ = event_tx.send(SessionEvent::Agent { event: envelope });
            }
            AgentEffect::FinishRun { .. } => {
                let _ = event_tx.send(SessionEvent::Completed);
                if let Ok(mut snap) = snapshot.lock() {
                    snap.status = SessionStatus::Completed;
                }
            }
            AgentEffect::ExecuteBackend { request } => {
                backend_requests.push(request.clone());
            }
            _ => {
                // SpawnAgent, ExecuteTool, RequestPermission, Persist,
                // CancelBackend, CancelTool, CancelChild — stubbed for this phase
            }
        }
    }

    // ── Phase 2: blocking I/O (backend execution) — spawn each backend
    //    request, collect streamed events, feed them back to the agent, and
    //    recursively process any resulting effects.

    for request in backend_requests {
        let run_id = request.run_id;
        let (backend_events_tx, mut backend_events_rx) = mpsc::channel(64);
        let backend = backend.clone();

        // Spawn backend execution in a separate task
        let handle = tokio::spawn(async move {
            backend.execute(request, backend_events_tx).await
        });

        // Collect streaming events from backend
        let mut collected_events: Vec<ExecutionEvent> = Vec::new();
        while let Some(ev) = backend_events_rx.recv().await {
            let is_terminal = matches!(
                &ev,
                ExecutionEvent::Completed { .. } | ExecutionEvent::Error { .. }
            );
            collected_events.push(ev);
            if is_terminal {
                // Drain any remaining events after terminal
                while let Some(remaining) = backend_events_rx.recv().await {
                    collected_events.push(remaining);
                }
                break;
            }
        }

        // Await the final result (for diagnostics — the terminal event
        // already carried completion info to the agent)
        let _result = handle.await.unwrap_or_else(|_| {
            Err(ExecutionError::BackendError {
                message: "backend task panicked".into(),
                code: "TASK_PANIC".into(),
            })
        });

        // Feed collected events to the agent state machine
        if !collected_events.is_empty() {
            let new_effects = {
                let mut guard = agent.lock().unwrap();
                let mut new_effects = Vec::new();
                for event in collected_events {
                    new_effects.extend(guard.apply(AgentCommand::BackendEvent {
                        run_id,
                        event,
                    }));
                }
                new_effects
            };
            // Recursively process effects from backend events
            Box::pin(process_effects(
                agent,
                backend,
                event_tx,
                snapshot,
                new_effects,
            ))
            .await;
        }
    }
}

// ---------------------------------------------------------------------------
// SessionBuilder
// ---------------------------------------------------------------------------

/// Builder for constructing and starting a session (spec §63).
///
/// # Example
///
/// ```rust,ignore
/// let session = harness
///     .session()             // SessionBuilder
///     .backend(backend)      // SessionBuilder with backend set
///     .tools(toolset)        // SessionBuilder with backend + tools
///     .start()               // Result<SessionHandle>
///     .await?;
/// ```
pub struct SessionBuilder {
    backend: Option<Arc<dyn ExecutionBackend>>,
    tools: Option<AgentToolset>,
}

impl SessionBuilder {
    /// Create a new empty builder.
    pub fn new() -> Self {
        Self {
            backend: None,
            tools: None,
        }
    }

    /// Set the execution backend for this session.
    pub fn backend(mut self, backend: Arc<dyn ExecutionBackend>) -> Self {
        self.backend = Some(backend);
        self
    }

    /// Set the toolset for this session's root agent.
    pub fn tools(mut self, tools: AgentToolset) -> Self {
        self.tools = Some(tools);
        self
    }

    /// Start the session and return a [`SessionHandle`].
    ///
    /// This spawns a background agent runtime loop and returns immediately.
    /// The returned handle can be used to send commands and subscribe to events.
    pub async fn start(self) -> Result<SessionHandle, Box<dyn std::error::Error>> {
        let backend = self
            .backend
            .ok_or_else(|| Box::<dyn std::error::Error>::from("backend is required"))?;
        let tools = self.tools.unwrap_or_else(|| AgentToolset {
            tools: std::collections::HashMap::new(),
        });

        let client = LocalSessionClient::new(backend, tools);
        Ok(SessionHandle::new(Arc::new(client)))
    }
}

impl Default for SessionBuilder {
    fn default() -> Self {
        Self::new()
    }
}

