//! Integration test: verify the full `Harness` → `SessionBuilder` → `SessionHandle`
//! builder chain produces a working session that accepts a prompt and yields events.
//!
//! This test matches the Phase 2 goal statement from spec §71 verbatim:
//!
//! > **Phase 2 — Single-session runtime**
//! > Goal: `session.send(prompt)` / `session.subscribe()` works end-to-end
//! > against a fake backend (spec §71 Phase 2 goal).
//!
//! The test mirrors the builder pattern from spec §12 / §63:
//!
//! ```rust,ignore
//! let session = harness
//!     .session()
//!     .backend(Arc::new(FakeBackend::new(...)))
//!     .tools(toolset)
//!     .start()
//!     .await?;
//! ```

use std::collections::HashMap;
use std::sync::Arc;

use async_trait::async_trait;
use tokio::sync::mpsc;
use tokio::time::{timeout, Duration};

use harness_engine::session_builder::{
    ExecutionBackend, SessionCommand, SessionEvent,
};
use harness_engine::Harness;
use harness_protocol::backend::{
    BackendCapabilities, BackendDescriptor, ExecutionError, ExecutionEvent, ExecutionRequest,
    ExecutionResult,
};
use harness_protocol::commands::UserInput;
use harness_protocol::ids::{BackendId, RequestId, ToolId};
use harness_protocol::tools::{
    AgentToolset, PermissionMode, ToolCapability, ToolDescriptor, ToolPolicy,
};
use harness_protocol::usage::ModelUsage;

// ---------------------------------------------------------------------------
// FakeBackend — deterministic, scripted backend for testing
// ---------------------------------------------------------------------------

/// A fake backend that emits scripted events and appends a terminal
/// [`ExecutionEvent::Completed`] if not already present.
struct FakeBackend {
    descriptor: BackendDescriptor,
    scripted_events: Vec<ExecutionEvent>,
    finish_reason: String,
}

impl FakeBackend {
    fn new(mut events: Vec<ExecutionEvent>, finish_reason: &str) -> Self {
        let has_terminal = events.iter().any(|e| {
            matches!(e, ExecutionEvent::Completed { .. } | ExecutionEvent::Error { .. })
        });
        if !has_terminal {
            // Derive a request_id from the last streaming event if available
            let rid = events
                .iter()
                .find_map(|e| match e {
                    ExecutionEvent::TextDelta { request_id, .. } => Some(*request_id),
                    ExecutionEvent::ReasoningDelta { request_id, .. } => Some(*request_id),
                    _ => None,
                })
                .unwrap_or_else(RequestId::new);

            events.push(ExecutionEvent::Completed {
                request_id: rid,
                result: ExecutionResult {
                    request_id: rid,
                    usage: ModelUsage::default(),
                    cost: harness_protocol::usage::Cost::default(),
                    finish_reason: finish_reason.into(),
                },
            });
        }
        Self {
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "fake-backend".into(),
                description: "Deterministic fake backend for integration tests".into(),
                capabilities: BackendCapabilities {
                    streaming: true,
                    tool_calls: false,
                    ..Default::default()
                },
            },
            scripted_events: events,
            finish_reason: finish_reason.into(),
        }
    }
}

#[async_trait]
impl ExecutionBackend for FakeBackend {
    fn descriptor(&self) -> BackendDescriptor {
        self.descriptor.clone()
    }

    fn capabilities(&self) -> BackendCapabilities {
        self.descriptor.capabilities
    }

    async fn execute(
        &self,
        request: ExecutionRequest,
        events_tx: mpsc::Sender<ExecutionEvent>,
    ) -> Result<ExecutionResult, ExecutionError> {
        for event in &self.scripted_events {
            if events_tx.send(event.clone()).await.is_err() {
                break;
            }
        }
        Ok(ExecutionResult {
            request_id: request.request_id,
            usage: ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: self.finish_reason.clone(),
        })
    }
}

// ---------------------------------------------------------------------------
// FakeToolset — minimal toolset for the root agent
// ---------------------------------------------------------------------------

fn fake_toolset() -> AgentToolset {
    let tool_id = ToolId::from_uuid(uuid::Uuid::from_u128(1));
    let mut tools = HashMap::new();
    tools.insert(
        tool_id,
        ToolCapability {
            descriptor: ToolDescriptor {
                id: tool_id,
                name: "test-tool".into(),
                description: "A test tool for integration tests".into(),
                input_schema: serde_json::json!({}),
            },
            policy: ToolPolicy {
                permission: PermissionMode::Allow,
                enabled: true,
            },
            delegatable: false,
        },
    );
    AgentToolset { tools }
}

// ---------------------------------------------------------------------------
// Integration test — spec §71 Phase 2 goal
// ---------------------------------------------------------------------------

#[tokio::test]
async fn harness_builds_session_sends_prompt_and_receives_events() {
    // ── Arrange ──────────────────────────────────────────────────────────

    // Script a fake backend to emit a single text delta (it auto-appends Completed)
    let request_id = RequestId::new();
    let fake_backend = FakeBackend::new(
        vec![ExecutionEvent::TextDelta {
            request_id,
            delta: "Hello from fake backend!".into(),
        }],
        "end_turn",
    );

    let toolset = fake_toolset();

    // ── Act ──────────────────────────────────────────────────────────────
    //
    // Build a session via the exact builder chain from spec §12 / §63:
    //
    //   harness.session().backend(fake_backend).tools(fake_toolset).start().await?
    //
    // returning a SessionHandle wrapping LocalSessionClient.

    let harness = Harness::new();
    let session = harness
        .session()
        .backend(Arc::new(fake_backend))
        .tools(toolset)
        .start()
        .await
        .expect("SessionBuilder::start() should succeed — spec §63");

    // Subscribe to events before sending the prompt so we don't miss anything
    let mut events = session.subscribe();

    // Send a prompt — this is the "session.send(prompt)" part of the Phase 2 goal
    session
        .send(SessionCommand::Prompt(UserInput {
            text: "Test prompt for integration test".into(),
            attachments: vec![],
        }))
        .await
        .expect("SessionHandle::send() should succeed — spec §76");

    // ── Assert ───────────────────────────────────────────────────────────
    //
    // Phase 2 goal (spec §71) verbatim:
    //   "session.send(prompt) / session.subscribe() works end-to-end
    //    against a fake backend"
    //
    // We verify by collecting events from the subscription and asserting
    // that the expected lifecycle events appear in order.

    let mut session_started = false;
    let mut got_assistant_delta = false;
    let mut got_completed = false;

    while let Ok(Some(event)) = timeout(Duration::from_secs(5), events.recv()).await {
        match event {
            SessionEvent::SessionStarted => {
                session_started = true;
            }
            SessionEvent::Agent { event: env } => {
                match env.event {
                    harness_protocol::events::AgentEvent::AssistantTextDelta { delta, .. } => {
                        got_assistant_delta = true;
                        assert_eq!(
                            delta, "Hello from fake backend!",
                            "AssistantTextDelta should carry the scripted text"
                        );
                    }
                    _ => {}
                }
            }
            SessionEvent::Completed => {
                got_completed = true;
                break;
            }
            _ => {}
        }
    }

    assert!(
        session_started,
        "SessionStarted must be emitted — session.send(prompt) / session.subscribe() \
         works end-to-end (spec §71 Phase 2 goal)"
    );
    assert!(
        got_assistant_delta,
        "AssistantTextDelta must be emitted from fake backend events — \
         session.send(prompt) / session.subscribe() works end-to-end \
         (spec §71 Phase 2 goal)"
    );
    assert!(
        got_completed,
        "Completed must be emitted after backend finishes — \
         session.send(prompt) / session.subscribe() works end-to-end \
         (spec §71 Phase 2 goal)"
    );
}

