        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
