        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "hello".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);
        runner.run().await;

        let envelope = evt_rx.try_recv().expect("should have received an event");
        assert_eq!(envelope.agent_id, agent_id);
        assert_eq!(envelope.session_id, session_id);

        match envelope.event {
            AgentEvent::RunStarted { .. } => {}
            ref other => panic!("expected RunStarted, got {other:?}"),
        }
    }

