                    request_id,
                    usage: harness_protocol::usage::ModelUsage::default(),
                    cost: harness_protocol::usage::Cost::default(),
                    finish_reason: "end_turn".into(),
                },
            },
        ];

        let inner_backend = FakeBackend::new(
            scripted_events,
            Ok(ExecutionResult {
                request_id,
                usage: harness_protocol::usage::ModelUsage::default(),
                cost: harness_protocol::usage::Cost::default(),
                finish_reason: "end_turn".into(),
            }),
        );

        // Wrap with a delay so the backend is "blocking" — this gives us
        // time to cancel while the backend is still in-flight.
        let backend = Arc::new(DelayedBackend::new(
            inner_backend,
            Duration::from_millis(100),
        ));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            dummy_agent(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );

        // Send StartRun to kick off the backend call
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "cancel this run".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Brief pause to let the runner enter the backend-dispatch path
        tokio::time::sleep(Duration::from_millis(50)).await;

        // Cancel the token while the backend is still in-flight
        cancel.cancel();

        // Drop the external sender so the loop can exit
        drop(cmd_tx);

        // Run the loop — it will detect cancellation, apply Cancel to the
        // agent, dispatch effects (broadcasting terminal events), and exit.
        runner.run().await;

        // ---- Assertion 1: Agent transitioned to Cancelled ----
        assert_eq!(
            runner.agent().state.status,
            AgentStatus::Cancelled,
            "agent should be Cancelled after token-based cancellation"
        );

        // ---- Assertion 2: A result was recorded ----
        let result = runner
            .last_result()
            .expect("FinishRun should set last_result");
        assert!(!result.summary.is_empty(), "cancellation should produce a summary");

        // ---- Assertion 3: Event stream ends with Completed(Cancelled) ----
        let mut events: Vec<AgentEvent> = Vec::new();
        while let Ok(envelope) = evt_rx.try_recv() {
            events.push(envelope.event);
        }

        // The last broadcast event must be Completed { outcome: Cancelled }.
        let last_event = events.last().expect("should have at least one event");
        match last_event {
            AgentEvent::Completed {
                outcome: AgentOutcome::Cancelled,
            } => {} // expected
            other => panic!(
                "last broadcast event should be Completed(Cancelled), got {other:?}"
            ),
        }

        // ---- Assertion 4: The Completed(Cancelled) is the terminal event ----
        // It must be at the last position with nothing after it.
        let cancelled_idx = events
            .iter()
            .rposition(|e| {
                matches!(e, AgentEvent::Completed {
                    outcome: AgentOutcome::Cancelled
                })
            })
            .expect("Completed(Cancelled) must exist in event stream");
        assert_eq!(
            cancelled_idx,
            events.len() - 1,
            "nothing should appear after Completed(Cancelled)"
        );

        // ---- Assertion 5: RunCancellation was triggered ----
        assert!(runner.run_cancel().is_cancelled(), "run_cancel should be cancelled");
    }

    /// Verifies that cancelling via the internal [`RunCancellation`] root
    /// token (rather than the external [`AgentTask`] token) also transitions
    /// the agent to `Cancelled` and emits the terminal event.
    #[tokio::test]
    async fn run_cancellation_root_cancel_transitions_to_cancelled() {
        let request_id = RequestId::new();
        let backend = Arc::new(DelayedBackend::new(
            FakeBackend::new(
                vec![
                    ExecutionEvent::TextDelta {
                        request_id,
                        delta: "before ".into(),
                    },
                ],
                Ok(ExecutionResult {
                    request_id,
                    usage: harness_protocol::usage::ModelUsage::default(),
                    cost: harness_protocol::usage::Cost::default(),
                    finish_reason: "end_turn".into(),
                }),
            ),
            Duration::from_millis(100),
        ));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, mut evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            dummy_agent(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );

        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "test".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        tokio::time::sleep(Duration::from_millis(50)).await;

        // Cancel via the RunCancellation root (simulates session-level cancel)
        runner.run_cancel().cancel();

        drop(cmd_tx);
        runner.run().await;

        assert_eq!(
            runner.agent().state.status,
            AgentStatus::Cancelled,
            "agent should be Cancelled after RunCancellation cancel"
        );
        assert!(runner.last_result().is_some());

        let mut events: Vec<AgentEvent> = Vec::new();
        while let Ok(envelope) = evt_rx.try_recv() {
            events.push(envelope.event);
        }
        let last_event = events.last().expect("should have events");
        assert!(
            matches!(last_event, AgentEvent::Completed {
                outcome: AgentOutcome::Cancelled
            }),
            "last event should be Completed(Cancelled)"
        );
    }
}

// ---------------------------------------------------------------------------
// DelayedBackend — test helper that adds a per-event delay
// ---------------------------------------------------------------------------

/// A decorator around [`FakeBackend`] that introduces a small delay
/// before the first event emission, giving the test time to cancel
/// the token while the backend is still in-flight.
///
/// This simulates a "blocking" backend call for cancellation tests.
#[cfg(test)]
struct DelayedBackend {
    inner: FakeBackend,
    delay: Duration,
}

#[cfg(test)]
impl DelayedBackend {
    fn new(inner: FakeBackend, delay: Duration) -> Self {
        Self { inner, delay }
    }
}

#[cfg(test)]
#[async_trait::async_trait]
impl crate::traits::ExecutionBackend for DelayedBackend {
    fn descriptor(&self) -> harness_protocol::backend::BackendDescriptor {
        self.inner.descriptor()
    }

    fn capabilities(&self) -> harness_protocol::backend::BackendCapabilities {
        self.inner.capabilities()
    }

    async fn execute(
        &self,
        request: harness_protocol::backend::ExecutionRequest,
        context: harness_protocol::backend::ExecutionContext,
        events: crate::traits::ExecutionEventSink,
        cancel: tokio_util::sync::CancellationToken,
    ) -> Result<harness_protocol::backend::ExecutionResult, harness_protocol::backend::ExecutionError>
    {
        // Wait for the delay or cancellation (whichever comes first).
        tokio::select! {
            _ = tokio::time::sleep(self.delay) => {}
            _ = cancel.cancelled() => {
                return Err(harness_protocol::backend::ExecutionError::Cancelled);
            }
        }

        self.inner.execute(request, context, events, cancel).await
    }
}

//! Hierarchical cancellation for agent runs (spec §35).
//!
//! Tokio's [`CancellationToken`] forms the backbone — we wrap it in a
//! [`RunCancellation`] scoped to a single agent run.  Child tokens are
//! derived for each backend call, tool call, or child agent spawned
//! during the run.  Cancelling the root propagates to all children
//! automatically.
//!
//! # Hierarchy
//!
//! ```text
//! Session token
//!   └── Agent run token (RunCancellation)
//!         ├── Backend call token
//!         ├── Tool call token
//!         └── Child agent token
//! ```
//!
//! When the run token is cancelled, all child tokens are immediately
//! cancelled, causing in-flight backend streams, tool executors, and
//! child agents to cease work (spec §35: "backend streams, tools,
//! processes").
//!
//! # Session-level integration
//!
//! The session runtime creates a [`CancellationToken`] per session that is
//! wired into the [`AgentTask`](crate::agent_runner::AgentTask) mailbox.
//! When the session receives a [`CancelRun`](crate::runtime::SessionCommand::CancelRun)
//! or [`CancelAgent`](crate::runtime::SessionCommand::CancelAgent) command,
//! the run-loop translates it into [`AgentCommand::Cancel`](harness_protocol::commands::AgentCommand::Cancel),
//! which flows through the agent state machine and triggers the
//! [`RunCancellation`] inside the runner.  The session also cancels its
//! own token as a safety net so that any in-flight backend or tool calls
//! are aborted immediately.

use tokio_util::sync::CancellationToken;

/// A hierarchical cancellation scope for a single agent run.
///
/// Create one per call to [`AgentRunner::run`] or per
/// [`AgentCommand::StartRun`].  The root token is used in the
/// runner's `tokio::select!` loop; child tokens are given to
/// every spawned backend or tool execution so that cancelling the
/// run automatically stops all in-flight work.
///
/// # Session-level usage
///
/// A session can create a [`RunCancellation`] that is a child of the
/// session's own [`CancellationToken`] via [`child_of`](Self::child_of).
/// This lets the session cancel all agent runs when it shuts down,
/// while still allowing individual agent runs to be cancelled
/// independently.
///
/// # Examples
///
/// ```ignore
/// use harness_runtime::cancellation::RunCancellation;
///
/// let run = RunCancellation::new();
///
/// // Hand a child token to a backend call
/// let backend_handle = run.child_token();
/// tokio::spawn(async move { backend.execute(..., backend_handle).await });
///
/// // Cancel the run — the backend task will receive cancellation
/// run.cancel();
/// ```
#[derive(Debug, Clone)]
pub struct RunCancellation {
    /// The root token for this run.  Cancelling it propagates to
    /// every child token created via [`child_token`](Self::child_token).
    root: CancellationToken,
}

impl RunCancellation {
    /// Create a new, un-cancelled run cancellation scope.
    pub fn new() -> Self {
        Self {
            root: CancellationToken::new(),
        }
    }

    /// Create a [`RunCancellation`] that is a child of the given parent
    /// [`CancellationToken`].
    ///
    /// When the parent token is cancelled, this run cancellation is also
    /// cancelled (and vice versa: cancelling this scope does **not**
    /// cancel the parent).
    ///
    /// This is useful for session-level orchestration: the session passes
    /// its own token as the parent so that shutting down the session
    /// propagates to all active agent runs.
    pub fn child_of(parent: &CancellationToken) -> Self {
        Self {
            root: parent.child_token(),
        }
    }

    /// Derive a new child token for a backend or tool execution.
    ///
    /// Multiple calls return independent child tokens.  Cancelling
    /// any one of them does **not** affect the root or other children;
    /// cancelling the root cancels all children.
    pub fn child_token(&self) -> CancellationToken {
        self.root.child_token()
    }

    /// Cancel the entire run.
    ///
    /// All existing child tokens (backend, tool, child agent) are
    /// immediately cancelled.  New child tokens created after this
    /// call will also start in the cancelled state.
    pub fn cancel(&self) {
        self.root.cancel();
    }

    /// Returns `true` if the run (or any ancestor) has been cancelled.
    pub fn is_cancelled(&self) -> bool {
        self.root.is_cancelled()
    }

    /// Returns a clone of the root token, suitable for use in the
    /// runner's `tokio::select!` loop to detect cancellation.
    pub fn token(&self) -> CancellationToken {
        self.root.clone()
    }
}

impl Default for RunCancellation {
    fn default() -> Self {
        Self::new()
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    /// A fresh `RunCancellation` is not cancelled.
    #[test]
    fn not_cancelled_by_default() {
        let run = RunCancellation::new();
        assert!(!run.is_cancelled());
    }

    /// Cancelling the root marks it as cancelled.
    #[test]
    fn cancel_marks_cancelled() {
        let run = RunCancellation::new();
        run.cancel();
        assert!(run.is_cancelled());
    }

    /// Child tokens share the cancellation state of the root.
    #[test]
    fn child_token_inherits_cancellation() {
        let run = RunCancellation::new();
        let child = run.child_token();
        assert!(!child.is_cancelled());

        run.cancel();
        assert!(child.is_cancelled());
    }

    /// Multiple child tokens are all cancelled when the root is cancelled.
    #[test]
    fn multiple_children_all_cancelled() {
        let run = RunCancellation::new();
        let c1 = run.child_token();
        let c2 = run.child_token();

        run.cancel();
        assert!(c1.is_cancelled());
        assert!(c2.is_cancelled());
    }

    /// Cloning `RunCancellation` shares the same root token.
    #[test]
    fn clone_shares_root() {
        let run_a = RunCancellation::new();
        let run_b = run_a.clone();

        run_a.cancel();
        assert!(run_b.is_cancelled());
    }

    /// New children created after cancellation are already cancelled.
    #[test]
    fn child_token_after_cancel_is_cancelled() {
        let run = RunCancellation::new();
        run.cancel();
        let child = run.child_token();
        assert!(child.is_cancelled());
    }

    /// `child_of` creates a scope that inherits from the parent token.
    #[test]
    fn child_of_inherits_parent_cancellation() {
        let parent = CancellationToken::new();
        let run = RunCancellation::child_of(&parent);
        assert!(!run.is_cancelled());

        parent.cancel();
        assert!(run.is_cancelled());
    }

    /// `child_of` does not propagate cancellation to the parent when the
    /// child scope is cancelled.
    #[test]
    fn child_of_does_not_cancel_parent() {
        let parent = CancellationToken::new();
        let run = RunCancellation::child_of(&parent);
        assert!(!parent.is_cancelled());

        run.cancel();
        // The parent should remain un-cancelled.
        assert!(!parent.is_cancelled());
        // The child scope itself is cancelled.
        assert!(run.is_cancelled());
    }
}

