//! Deterministic fake [`ToolExecutor`] for testing.
//!
//! This module provides [`FakeToolExecutor`], a scriptable implementation
//! of the [`ToolExecutor`](crate::traits::ToolExecutor) trait that returns
//! pre-configured results or errors, enabling deterministic testing of
//! tool-registry, agent-runner, and higher-level orchestration logic
//! without performing real I/O.

use std::collections::VecDeque;
use std::sync::Mutex;

use async_trait::async_trait;
use tokio_util::sync::CancellationToken;

use harness_protocol::ids::ToolCallId;
use harness_protocol::tools::{ToolDescriptor, ToolError, ToolProgress, ToolResult};

use crate::traits::{ToolEventSink, ToolExecutionContext, ToolExecutor};

// ---------------------------------------------------------------------------
// FakeToolOutcome
// ---------------------------------------------------------------------------

/// A scripted outcome for a single tool invocation.
///
/// Used with [`FakeToolExecutor`] to specify what a given tool call should
/// return when [`execute`](FakeToolExecutor::execute) is invoked.
#[derive(Debug, Clone)]
pub enum FakeToolOutcome {
    /// The executor returns `Ok(result)`, producing a successful tool
    /// response with the given [`ToolResult`].
    Ok(ToolResult),

    /// The executor returns `Err(error)`, signalling a tool-level failure.
    Err(ToolError),
}

impl FakeToolOutcome {
    /// Shorthand for a successful (non-error) result.
    ///
    /// Equivalent to `FakeToolOutcome::Ok(ToolResult { call_id, output, is_error: false })`.
    pub fn ok(call_id: ToolCallId, output: serde_json::Value) -> Self {
        Self::Ok(ToolResult {
            call_id,
            output,
            is_error: false,
        })
    }

    /// Shorthand for a logical error result (the tool ran but indicates a
    /// problem in its output, such as "file not found").
    ///
    /// Equivalent to `FakeToolOutcome::Ok(ToolResult { call_id, output, is_error: true })`.
    pub fn error_result(call_id: ToolCallId, output: serde_json::Value) -> Self {
        Self::Ok(ToolResult {
            call_id,
            output,
            is_error: true,
        })
    }

    /// Shorthand for an executor-level failure.
    ///
    /// Equivalent to `FakeToolOutcome::Err(error)`.
    pub fn err(error: ToolError) -> Self {
        Self::Err(error)
    }
}

// ---------------------------------------------------------------------------
// FakeToolExecutor
// ---------------------------------------------------------------------------

/// A fake [`ToolExecutor`] that returns pre-scripted outcomes in sequence.
///
/// Each call to [`execute`](FakeToolExecutor::execute) consumes the next
/// outcome from the script queue.  When the script is exhausted the
/// executor returns `Err(ToolError::Internal)`.
///
/// The executor is `Send + Sync` and can be stored as
/// `Arc<dyn ToolExecutor>` for use in [`ToolRegistry`](crate::traits::ToolRegistry)
/// and agent-runner tests.
///
/// # Determinism
///
/// Outcomes are consumed in strict FIFO order — the first call to
/// `execute` returns the first scripted outcome, the second call returns
/// the second, and so on.  This makes tests fully deterministic as long
/// as the number of expected tool invocations matches the script length.
///
/// # Cancellation
///
/// If the [`CancellationToken`] is cancelled before the outcome is
/// popped, the executor returns `Err(ToolError::Timeout)` immediately.
///
/// # Example
///
/// ```ignore
/// use harness_protocol::ids::ToolCallId;
/// use harness_protocol::tools::{ToolDescriptor, ToolError, ToolResult};
/// use harness_runtime::testing::fake_tools::{FakeToolExecutor, FakeToolOutcome};
/// use harness_runtime::traits::ToolExecutionContext;
/// use tokio_util::sync::CancellationToken;
/// use tokio::sync::mpsc;
///
/// let descriptor = ToolDescriptor {
///     id: ToolId::new(),
///     name: "test_tool".into(),
///     description: "A fake tool for testing".into(),
///     input_schema: serde_json::json!({}),
/// };
///
/// let call_id = ToolCallId::new();
/// let outcomes = vec![
///     FakeToolOutcome::ok(call_id, serde_json::json!({"result": "success"})),
///     FakeToolOutcome::err(ToolError::ExecutionFailed),
/// ];
///
/// let executor = FakeToolExecutor::new(descriptor, outcomes);
/// let (_tx, rx) = mpsc::unbounded_channel();
/// let cancel = CancellationToken::new();
/// let context = ToolExecutionContext::new();
///
/// // First call → Ok
/// let result = executor.execute(context.clone(), serde_json::json!({}), rx.clone(), cancel.clone()).await;
/// assert!(result.is_ok());
///
/// // Second call → Err(ExecutionFailed)
/// let result = executor.execute(context, serde_json::json!({}), rx, cancel).await;
/// assert!(result.is_err());
/// ```
pub struct FakeToolExecutor {
    /// The static descriptor returned by [`descriptor()`](Self::descriptor).
    descriptor: ToolDescriptor,
    /// The queue of remaining scripted outcomes, protected by a mutex for
    /// interior mutability (required because `execute` takes `&self`).
    outcomes: Mutex<VecDeque<FakeToolOutcome>>,
}

impl FakeToolExecutor {
    /// Creates a new executor with the given `descriptor` and scripted
    /// `outcomes`.
    ///
    /// The outcomes are consumed in FIFO order — the first call to
    /// [`execute`](Self::execute) returns the first outcome, the second
    /// call returns the second, and so on.
    pub fn new(descriptor: ToolDescriptor, outcomes: Vec<FakeToolOutcome>) -> Self {
        Self {
            descriptor,
            outcomes: Mutex::new(VecDeque::from(outcomes)),
        }
    }

    /// Creates a new executor with the given `descriptor` and an empty
    /// script.
    ///
    /// Every call to [`execute`](Self::execute) will return
    /// `Err(ToolError::Internal)` until outcomes are added via
    /// [`push_outcome`](Self::push_outcome).
    pub fn with_descriptor(descriptor: ToolDescriptor) -> Self {
        Self {
            descriptor,
            outcomes: Mutex::new(VecDeque::new()),
        }
    }

    /// Appends an outcome to the end of the script queue.
    ///
    /// This can be called at any time — even after some outcomes have
    /// already been consumed — to extend the script dynamically.
    ///
    /// # Panics
    ///
    /// Panics if the internal mutex is poisoned (a panic occurred while
    /// the lock was held in another thread).
    pub fn push_outcome(&self, outcome: FakeToolOutcome) {
        self.outcomes
            .lock()
            .expect("FakeToolExecutor outcome lock poisoned")
            .push_back(outcome);
    }
}

#[async_trait]
impl ToolExecutor for FakeToolExecutor {
    fn descriptor(&self) -> ToolDescriptor {
        self.descriptor.clone()
    }

    async fn execute(
        &self,
        _context: ToolExecutionContext,
        _arguments: serde_json::Value,
        events: ToolEventSink,
        cancel: CancellationToken,
    ) -> Result<ToolResult, ToolError> {
        // Honour cancellation — check at the entry point before
        // accessing any internal state.
        if cancel.is_cancelled() {
            let _ = events.send(ToolProgress {
                status: "cancelled".into(),
                fraction: 1.0,
            });
            return Err(ToolError::Timeout);
        }

        // Pop the next scripted outcome from the front of the queue.
        let outcome = {
            let mut guard = self
                .outcomes
                .lock()
                .expect("FakeToolExecutor outcome lock poisoned");
            guard.pop_front()
        };

        match outcome {
            None => {
                // Script exhausted — no outcome remains to return.
                let _ = events.send(ToolProgress {
                    status: "internal error — no scripted outcome available".into(),
                    fraction: 1.0,
                });
                Err(ToolError::Internal)
            }
            Some(FakeToolOutcome::Ok(result)) => {
                let _ = events.send(ToolProgress {
                    status: "completed".into(),
                    fraction: 1.0,
                });
                Ok(result)
            }
            Some(FakeToolOutcome::Err(error)) => {
                let _ = events.send(ToolProgress {
                    status: "error".into(),
                    fraction: 1.0,
                });
                Err(error)
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::sync::mpsc;

    fn test_descriptor() -> ToolDescriptor {
        ToolDescriptor {
            id: harness_protocol::ids::ToolId::new(),
            name: "fake_test_tool".into(),
            description: "A fake tool used in unit tests".into(),
            input_schema: serde_json::json!({}),
        }
    }

    #[tokio::test]
    async fn returns_scripted_ok_outcome() {
        let call_id = ToolCallId::new();
        let expected_output = serde_json::json!({"result": "hello"});
        let outcomes = vec![FakeToolOutcome::ok(call_id, expected_output.clone())];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok result");

        assert_eq!(result.call_id, call_id);
        assert_eq!(result.output, expected_output);
        assert!(!result.is_error);
    }

    #[tokio::test]
    async fn returns_scripted_err_outcome() {
        let outcomes = vec![FakeToolOutcome::err(ToolError::ExecutionFailed)];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let err = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect_err("expected Err");

        assert!(matches!(err, ToolError::ExecutionFailed));
    }

    #[tokio::test]
    async fn returns_error_result_outcome() {
        let call_id = ToolCallId::new();
        let output = serde_json::json!({"error": "file not found"});
        let outcomes = vec![FakeToolOutcome::error_result(call_id, output.clone())];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok result (with is_error flag)");

        assert_eq!(result.call_id, call_id);
        assert_eq!(result.output, output);
        assert!(result.is_error);
    }

    #[tokio::test]
    async fn consumes_outcomes_in_fifo_order() {
        let call_id_a = ToolCallId::new();
        let call_id_b = ToolCallId::new();
        let outcomes = vec![
            FakeToolOutcome::ok(call_id_a, serde_json::json!({"seq": 1})),
            FakeToolOutcome::ok(call_id_b, serde_json::json!({"seq": 2})),
        ];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        // First call → outcome 0
        let r1 = executor
            .execute(context.clone(), serde_json::json!({}), tx.clone(), cancel.clone())
            .await
            .expect("expected Ok on first call");
        assert_eq!(r1.call_id, call_id_a);

        // Second call → outcome 1
        let r2 = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok on second call");
        assert_eq!(r2.call_id, call_id_b);
    }

    #[tokio::test]
    async fn returns_internal_when_script_exhausted() {
        let outcomes = vec![FakeToolOutcome::ok(
            ToolCallId::new(),
            serde_json::json!({"only": "one"}),
        )];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        // First call succeeds
        executor
            .execute(context.clone(), serde_json::json!({}), tx.clone(), cancel.clone())
            .await
            .expect("expected Ok on first call");

        // Second call fails because script is exhausted
        let err = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect_err("expected Err on exhausted script");
        assert!(matches!(err, ToolError::Internal));
    }

    #[tokio::test]
    async fn returns_timeout_on_cancellation() {
        let outcomes = vec![FakeToolOutcome::ok(
            ToolCallId::new(),
            serde_json::json!({"should": "not run"}),
        )];
        let executor = FakeToolExecutor::new(test_descriptor(), outcomes);

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        cancel.cancel();
        let context = ToolExecutionContext::new();

        let err = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect_err("expected Err on cancelled token");
        assert!(matches!(err, ToolError::Timeout));
    }

    #[tokio::test]
    async fn push_outcome_during_execution() {
        let executor = FakeToolExecutor::with_descriptor(test_descriptor());

        // No outcomes yet — first call should fail.
        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let err = executor
            .execute(context.clone(), serde_json::json!({}), tx.clone(), cancel.clone())
            .await
            .expect_err("expected Err on empty script");
        assert!(matches!(err, ToolError::Internal));

        // Add an outcome and try again.
        let call_id = ToolCallId::new();
        executor.push_outcome(FakeToolOutcome::ok(call_id, serde_json::json!({"late": "ok"})));

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok after push_outcome");
        assert_eq!(result.call_id, call_id);
    }

    #[tokio::test]
    async fn descriptor_trait_and_inherent_methods_agree() {
        let descriptor = test_descriptor();
        let executor = FakeToolExecutor::with_descriptor(descriptor.clone());

        // Call through the inherent method
        let d1 = executor.descriptor();
        // Call through a &dyn ToolExecutor reference (trait dispatch)
        let d2 = <dyn ToolExecutor>::descriptor(&executor);

        assert_eq!(d1.id, descriptor.id);
        assert_eq!(d2.id, descriptor.id);
        assert_eq!(d1.name, d2.name);
    }

    #[tokio::test]
    async fn shared_via_arc_dyn_tool_executor() {
        use std::sync::Arc;

        let descriptor = test_descriptor();
        let outcomes = vec![FakeToolOutcome::ok(
            ToolCallId::new(),
            serde_json::json!({"via": "arc"}),
        )];
        let executor: Arc<dyn ToolExecutor> =
            Arc::new(FakeToolExecutor::new(descriptor, outcomes));

        let (tx, _rx) = mpsc::unbounded_channel();
        let cancel = CancellationToken::new();
        let context = ToolExecutionContext::new();

        let result = executor
            .execute(context, serde_json::json!({}), tx, cancel)
            .await
            .expect("expected Ok via Arc<dyn ToolExecutor>");
        assert_eq!(result.output, serde_json::json!({"via": "arc"}));
    }
}

//! Session client API — the primary frontend-facing handle for interacting
//! with a live session (spec §48, §76).
//!
//! This module defines the [`SessionClient`] trait and its primary
//! implementation, [`SessionApi`], which wraps an [`SessionRuntime`] and
//! provides a clean async interface for sending commands, taking
//! snapshots, and subscribing to events.
//!
//! # Architecture (spec §48)
//!
//! ```text
//! Frontend (IDE, TUI, WebSocket)
//!   │
//!   │  SessionClient trait
//!   │    ├── send(SessionCommand)     → drives session lifecycle
//!   │    ├── snapshot()               → T17 projection of live state
//!   │    └── subscribe()              → SessionEvent stream
//!   │
//!   ▼
//! SessionApi (concrete impl)
//!   │
//!   ├── SessionRuntime (event loop, agent runner, event bus)
//!   └── Arc<SessionRuntime> (shared ownership)
//! ```

use std::sync::Arc;

use tokio::sync::broadcast;

use crate::runtime::{SessionCommand, SessionError, SessionEvent, SessionRuntime};
use crate::snapshot::SessionSnapshot;

// ---------------------------------------------------------------------------
// SessionEventStream
// ---------------------------------------------------------------------------

/// A stream of [`SessionEvent`]s emitted by a session.
///
/// This is a [`tokio::sync::broadcast::Receiver`] that yields session-level
/// events including agent events, lifecycle changes, and usage updates.
///
/// Multiple frontend components can independently subscribe to the same
/// session's event bus; each gets its own [`SessionEventStream`] with a
/// buffer that starts at the subscription moment (no replay of past events).
pub type SessionEventStream = broadcast::Receiver<SessionEvent>;

// ---------------------------------------------------------------------------
// SessionClient trait  (spec §48)
// ---------------------------------------------------------------------------

/// The primary API for interacting with a live session.
///
/// Implementations wrap a [`SessionRuntime`] and provide a clean,
/// frontend-friendly interface for:
///
/// * Sending commands ([`send`](Self::send)) — prompts, cancellations,
///   pause/resume, and permission decisions.
/// * Taking point-in-time snapshots ([`snapshot`](Self::snapshot)) of the
///   session's current state via the T17 projection.
/// * Subscribing to the session-level event stream
///   ([`subscribe`](Self::subscribe)) for reactive UI updates.
///
/// # Examples
///
/// ```rust,ignore
/// use harness_runtime::handles::{SessionClient, SessionApi};
///
/// let api = SessionApi::new(runtime_arc);
///
/// // Send a prompt to start a run
/// api.send(SessionCommand::Prompt(input)).await?;
///
/// // Inspect live state
/// let snap = api.snapshot().await?;
/// println!("Session status: {:?}", snap.status);
///
/// // Subscribe for events
/// let mut stream = api.subscribe();
/// while let Ok(event) = stream.recv().await {
///     // handle event
/// }
/// ```
pub trait SessionClient {
    /// Send a [`SessionCommand`] to the session's run loop.
    ///
    /// Returns `Ok(())` if the command was accepted, or a [`SessionError`]
    /// if the session has already shut down (the receiver was dropped).
    async fn send(
        &self,
        command: SessionCommand,
    ) -> Result<(), SessionError>;

    /// Return a point-in-time [`SessionSnapshot`] of the session's live
    /// state (spec §45).
    ///
    /// The snapshot includes session identity, lifecycle status, aggregated
    /// usage, and agent snapshots for all active agents.  It is a pure
    /// in-memory read — no I/O or locks are involved.
    ///
    /// This is the T17 projection referenced in the architecture:
    /// a throwaway read used for display, debugging, and inspection.
    async fn snapshot(
        &self,
    ) -> Result<SessionSnapshot, SessionError>;

    /// Subscribe to the session-level event stream.
    ///
    /// Returns a [`SessionEventStream`] (a
    /// [`broadcast::Receiver<SessionEvent>`]) that yields all session
    /// events — agent events (with monotonically increasing
    /// `session_sequence` values), lifecycle changes (`StatusChanged`,
    /// `Completed`, `Failed`), and usage updates.
    ///
    /// Each call creates an independent subscriber starting at the current
    /// broadcast buffer head.  Late subscribers will miss earlier events.
    fn subscribe(&self) -> SessionEventStream;
}

// ---------------------------------------------------------------------------
// SessionApi  (spec §76)
// ---------------------------------------------------------------------------

/// A concrete [`SessionClient`] implementation that wraps an
/// [`Arc<SessionRuntime>`].
///
/// `SessionApi` is the standard frontend-facing handle for a live session.
/// It is cheaply cloneable (the `Arc` is shared) and provides the full
/// [`SessionClient`] API.
///
/// # Construction
///
/// ```rust,ignore
/// use std::sync::Arc;
/// use harness_runtime::handles::SessionApi;
/// use harness_runtime::runtime::SessionRuntime;
///
/// let runtime = SessionRuntime::new(/* ... */);
/// let api = SessionApi::new(Arc::new(runtime));
/// ```
///
/// # Thread safety
///
/// `SessionApi` is `Send + Sync` because all mutable state is inside the
/// `SessionRuntime` which uses internal synchronization (MPSC channels,
/// atomics, broadcast).  Multiple tasks can hold clones of the same
/// `SessionApi` and interact with the session concurrently.
#[derive(Debug, Clone)]
pub struct SessionApi {
    /// The shared session runtime that backs all operations.
    runtime: Arc<SessionRuntime>,
}

impl SessionApi {
    /// Create a new [`SessionApi`] from an [`Arc<SessionRuntime>`].
    ///
    /// This is the standard construction path.  The `Arc` allows the handle
    /// to be cheaply cloned and shared across tasks.
    pub fn new(runtime: Arc<SessionRuntime>) -> Self {
        Self { runtime }
    }

    /// Returns a reference to the inner [`SessionRuntime`].
    ///
    /// This can be used to access runtime internals (e.g., for testing or
    /// advanced configuration) without going through the `SessionClient`
    /// trait.
    pub fn runtime(&self) -> &SessionRuntime {
        &self.runtime
    }
}

impl SessionClient for SessionApi {
    /// Send a command to the session's run loop.
    ///
    /// Delegates to [`SessionRuntime::send_command`], converting the MPSC
    /// [`SendError`](tokio::sync::mpsc::error::SendError) into a
    /// [`SessionError`] with code `"SESSION_SHUTDOWN"`.
    async fn send(
        &self,
        command: SessionCommand,
    ) -> Result<(), SessionError> {
        self.runtime
            .send_command(command)
            .await
            .map_err(|_| SessionError {
                message: "session run loop has shut down".into(),
                code: "SESSION_SHUTDOWN".into(),
            })
    }

    /// Return a point-in-time [`SessionSnapshot`] via the T17 projection.
    ///
    /// Delegates to [`SessionRuntime::snapshot`] which is a pure in-memory
    /// read.  This method always returns `Ok` — the snapshot is constructed
    /// from live state without I/O.
    async fn snapshot(
        &self,
    ) -> Result<SessionSnapshot, SessionError> {
        Ok(self.runtime.snapshot())
    }

    /// Subscribe to the session-level event stream.
    ///
    /// Delegates to [`SessionEventBus::subscribe`] on the runtime's event
    /// bus.  Each call returns an independent receiver.
    fn subscribe(&self) -> SessionEventStream {
        self.runtime.event_bus.subscribe()
    }
}

