    /// Multiple subscribers each receive all events.
    #[tokio::test]
    async fn multiple_subscribers_receive_events() {
        use harness_protocol::usage::{Cost, ModelUsage};

        let request_id = RequestId::new();

        let runtime = build_test_runtime(
            vec![],
            Ok(ExecutionResult {
                request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            }),
        );
        let api = SessionApi::new(runtime);

        let mut stream1 = api.subscribe();
        let mut stream2 = api.subscribe();

        let ev1 = tokio::time::timeout(Duration::from_secs(5), stream1.recv())
            .await
            .expect("timeout")
            .expect("recv");
        let ev2 = tokio::time::timeout(Duration::from_secs(5), stream2.recv())
            .await
            .expect("timeout")
            .expect("recv");

        assert!(matches!(ev1, SessionEvent::SessionStarted));
        assert!(matches!(ev2, SessionEvent::SessionStarted));
    }

    // -----------------------------------------------------------------------
    // SessionClient end-to-end integration
    // -----------------------------------------------------------------------

    /// Full integration: send a prompt, collect events, verify the event
    /// stream is well-ordered and terminates with
    /// [`SessionEvent::Completed`].
    #[tokio::test]
    async fn full_integration_via_session_client() {
        use harness_protocol::usage::{Cost, ModelUsage};

        let request_id = RequestId::new();

        let scripted_events = vec![
            ExecutionEvent::TextDelta {
                request_id,
                delta: "Hello from SessionClient! ".into(),
            },
            ExecutionEvent::Completed {
                request_id,
                result: ExecutionResult {
                    request_id,
                    usage: ModelUsage::default(),
                    cost: Cost::default(),
                    finish_reason: "end_turn".into(),
                },
            },
        ];

        let runtime = build_test_runtime(
            scripted_events,
            Ok(ExecutionResult {
                request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            }),
        );
        let api = SessionApi::new(Arc::clone(&runtime));

        let mut events = api.subscribe();

        // Send a prompt.
        api.send(SessionCommand::Prompt(UserInput {
            text: "run integration test".into(),
            attachments: vec![],
        }))
        .await
        .expect("send Prompt");

        // Collect events until Completed.
        let mut collected: Vec<SessionEvent> = Vec::new();
        loop {
            let result =
                tokio::time::timeout(Duration::from_secs(5), events.recv()).await;
            match result {
                Ok(Ok(event)) => {
                    let is_terminal = matches!(
                        event,
                        SessionEvent::Completed | SessionEvent::Failed { .. }
                    );
                    collected.push(event);
                    if is_terminal {
                        break;
                    }
                }
                Ok(Err(broadcast::error::RecvError::Closed)) => break,
                Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
                Err(_) => {
                    panic!(
                        "timed out; collected {} events",
                        collected.len()
                    );
                }
            }
        }

        // Must have SessionStarted first.
        assert!(
            matches!(collected[0], SessionEvent::SessionStarted),
            "first event should be SessionStarted"
        );

        // Must end with Completed.
        assert!(
            matches!(collected.last().unwrap(), SessionEvent::Completed),
            "last event should be Completed"
        );

        // There should be at least one Agent event.
        let agent_count = collected
            .iter()
            .filter(|e| matches!(e, SessionEvent::Agent { .. }))
            .count();
        assert!(
            agent_count > 0,
            "expected at least one Agent event in the stream"
        );
    }
}

