//! In-memory [`FakeWorkspace`] — a trivial test double for the [`Workspace`] trait.
//!
//! # Examples
//!
//! ```ignore
//! use std::path::Path;
//! use harness_runtime::testing::fake_workspace::FakeWorkspace;
//! use harness_runtime::traits::{Workspace, SearchQuery};
//!
//! let ws = FakeWorkspace::new();
//!
//! // Write a file.
//! ws.write(Path::new("hello.txt"), b"Hello, world!").await.unwrap();
//!
//! // Read it back.
//! let contents = ws.read(Path::new("hello.txt")).await.unwrap();
//! assert_eq!(contents, b"Hello, world!");
//!
//! // Search for content.
//! let result = ws.search(SearchQuery {
//!     pattern: "world".into(),
//!     path_pattern: None,
//! }).await.unwrap();
//! assert_eq!(result.total, 1);
//!
//! // Check status.
//! let status = ws.status().await.unwrap();
//! assert_eq!(status.file_count, 1);
//! ```

use std::collections::HashMap;
use std::path::Path;
use std::sync::Mutex;

use async_trait::async_trait;

use crate::traits::{
    SearchMatch, SearchQuery, SearchResult, Workspace, WorkspaceError, WorkspaceStatus,
};

/// A trivial in-memory workspace that satisfies the [`Workspace`] trait.
///
/// All data is stored in a `HashMap<PathBuf, Vec<u8>>` behind a
/// `std::sync::Mutex`.  No I/O is performed — this is strictly a test
/// double.
///
/// ## Behaviour
///
/// | Method | Behaviour |
/// |---|---|
/// | `read` | Returns the bytes if the path exists, else [`WorkspaceError::NotFound`]. |
/// | `write` | Inserts or overwrites the entry for the given path. |
/// | `search` | Performs a naive case-sensitive substring search over path strings and file contents. |
/// | `status` | Returns the file count and total byte size of all stored files. |
///
/// ## Thread safety
///
/// `FakeWorkspace` is `Send + Sync` and can be shared behind
/// `Arc<dyn Workspace>`.
#[derive(Debug, Default)]
pub struct FakeWorkspace {
    /// Internal file storage.
    files: Mutex<HashMap<std::path::PathBuf, Vec<u8>>>,
}

impl FakeWorkspace {
    /// Create an empty fake workspace.
    pub fn new() -> Self {
        Self::default()
    }

    /// Return the number of files currently stored.
    pub fn file_count(&self) -> usize {
        self.files.lock().unwrap().len()
    }

    /// Return the total byte size of all stored files.
    pub fn total_size(&self) -> u64 {
        self.files
            .lock()
            .unwrap()
            .values()
            .map(|data| data.len() as u64)
            .sum()
    }
}

#[async_trait]
impl Workspace for FakeWorkspace {
    async fn read(&self, path: &Path) -> Result<Vec<u8>, WorkspaceError> {
        let files = self.files.lock().unwrap();
        files
            .get(path)
            .cloned()
            .ok_or_else(|| WorkspaceError::NotFound(path.display().to_string()))
    }

    async fn write(&self, path: &Path, data: &[u8]) -> Result<(), WorkspaceError> {
        let mut files = self.files.lock().unwrap();
        files.insert(path.to_path_buf(), data.to_vec());
        Ok(())
    }

    async fn search(&self, query: SearchQuery) -> Result<SearchResult, WorkspaceError> {
        let files = self.files.lock().unwrap();
        let pattern = query.pattern.to_lowercase();
        let mut matches = Vec::new();

        for (path, content) in files.iter() {
            let path_str = path.display().to_string();

            // Optionally filter by path pattern (simple substring match).
            if let Some(ref path_filter) = query.path_pattern {
                if !path_str.to_lowercase().contains(&path_filter.to_lowercase()) {
                    continue;
                }
            }

            let content_str = String::from_utf8_lossy(content);
            for (line_num, line) in content_str.lines().enumerate() {
                if line.to_lowercase().contains(&pattern) {
                    matches.push(SearchMatch {
                        path: path_str.clone(),
                        line: line_num + 1,
                        line_content: line.to_string(),
                    });
                }
            }
        }

        let total = matches.len();
        Ok(SearchResult {
            matches,
            total,
            truncated: false,
        })
    }

    async fn status(&self) -> Result<WorkspaceStatus, WorkspaceError> {
        let files = self.files.lock().unwrap();
        let file_count = files.len();
        let total_size_bytes: u64 = files.values().map(|d| d.len() as u64).sum();
        Ok(WorkspaceStatus {
            file_count,
            total_size_bytes,
        })
    }
}

