    /// When the agent enters `WaitingForPermission` (tool with `Ask` mode),
    /// the runner blocks until a matching `PermissionResolved` arrives.
    ///
    /// This test drives the full cycle:
    ///   StartRun → BackendEvent(ToolCallRequested) → PermissionResolved → Cancel
    #[tokio::test]
    async fn request_permission_awaits_resolution() {
        let backend = Arc::new(FakeBackend::new(vec![], Ok(ExecutionResult {
            request_id: RequestId::new(),
            usage: harness_protocol::usage::ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: "end_turn".into(),
        })));

        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::channel(16);
        let (evt_tx, _evt_rx) = tokio::sync::broadcast::channel(64);
        let cancel = tokio_util::sync::CancellationToken::new();

        // Subscribe to the event bus BEFORE the sender is moved into the runner.
        let mut event_sub = evt_tx.subscribe();

        let task = AgentTask {
            id: AgentId::new(),
            commands: cmd_rx,
            events: evt_tx,
            cancel: cancel.clone(),
        };

        let tool_registry = ToolRegistry::new();
        let mut runner = AgentRunner::new(
            agent_with_ask_tool(),
            task,
            backend,
            tool_registry,
            cmd_tx.clone(),
        );

        // Send StartRun to kick off a run
        cmd_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "read a file".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Spawn the runner in a background task so we can interact with
        // it while it's blocked waiting for permission.
        let (result_tx, mut result_rx) = tokio::sync::mpsc::channel(1);
        let handle = tokio::spawn(async move {
            runner.run().await;
            let _ = result_tx.send(runner).await;
        });

        // Read events until we get RunStarted (to learn the run_id).
        let run_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::RunStarted { run_id } = envelope.event {
                        break run_id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Trigger a tool call request to put the agent in WaitingForPermission.
        let call = ToolCall {
            id: ToolCallId::new(),
            name: "test.read".into(),
            arguments: serde_json::json!({"path": "/tmp/test.txt"}),
        };
        cmd_tx
            .send(AgentCommand::BackendEvent {
                run_id,
                event: ExecutionEvent::ToolCallRequested {
                    request_id: RequestId::new(),
                    call,
                },
            })
            .await
            .expect("send ToolCallRequested");

        // Read the PermissionRequested event to get the permission ID.
        let permission_id = loop {
            match event_sub.recv().await {
                Ok(envelope) => {
                    if let AgentEvent::PermissionRequested { ref request } = envelope.event {
                        break request.id;
                    }
                }
                Err(e) => panic!("event stream error: {e:?}"),
            }
        };

        // Resolve the permission (approve it).
        cmd_tx
            .send(AgentCommand::PermissionResolved {
                id: permission_id,
                decision: PermissionDecision::Approved,
            })
            .await
            .expect("send PermissionResolved");

        // Clean up by cancelling the run.
        cmd_tx
            .send(AgentCommand::Cancel)
            .await
            .expect("send Cancel");

        drop(cmd_tx);

        // Wait for the runner to finish and retrieve it.
        let _ = handle.await;
        let runner = result_rx
            .recv()
            .await
            .expect("runner should complete and be sent back");

        assert!(
            runner.last_result().is_some(),
            "expected a finish result after permission resolution"
        );
    }

