//! High-level public harness and session API plus runtime composition.
//!
//! # Crate structure
//!
//! | Module | Contents |
//! |---|---|
//! | [`harness`](crate::harness) | [`Harness`](crate::harness::Harness) — top-level entry point |
//! | [`session_builder`](crate::session_builder) | Builder chain, handle, and in-process session runtime |

pub mod harness;
