pub use harness::Harness;
pub use session_builder::{SessionBuilder, SessionHandle, SessionClient, SessionCommand, SessionEvent, SessionEventStream, SessionSnapshot, SessionStatus, SessionError, LocalSessionClient, ExecutionBackend};

//! Integration test: verify the full `Harness` → `SessionBuilder` → `SessionHandle`
//! builder chain produces a working session that accepts a prompt and yields events.
//!
//! This test matches the Phase 2 goal statement from spec §71 verbatim:
//!
//! > **Phase 2 — Single-session runtime**
//! > Goal: `session.send(prompt)` / `session.subscribe()` works end-to-end
//! > against a fake backend (spec §71 Phase 2 goal).
//!
//! The test mirrors the builder pattern from spec §12 / §63:
//!
//! ```rust,ignore
//! let session = harness
//!     .session()
//!     .backend(Arc::new(FakeBackend::new(...)))
//!     .tools(toolset)
//!     .start()
//!     .await?;
//! ```

use std::collections::HashMap;
use std::sync::Arc;

use async_trait::async_trait;
use tokio::sync::mpsc;
use tokio::time::{timeout, Duration};

use harness_engine::session_builder::{
    ExecutionBackend, SessionCommand, SessionEvent,
};
use harness_engine::Harness;
use harness_protocol::backend::{
    BackendCapabilities, BackendDescriptor, ExecutionError, ExecutionEvent, ExecutionRequest,
    ExecutionResult,
};
use harness_protocol::commands::UserInput;
use harness_protocol::ids::{BackendId, RequestId, ToolId};
use harness_protocol::tools::{
    AgentToolset, PermissionMode, ToolCapability, ToolDescriptor, ToolPolicy,
};
use harness_protocol::usage::ModelUsage;

// ---------------------------------------------------------------------------
// FakeBackend — deterministic, scripted backend for testing
// ---------------------------------------------------------------------------

/// A fake backend that emits scripted events and appends a terminal
/// [`ExecutionEvent::Completed`] if not already present.
struct FakeBackend {
    descriptor: BackendDescriptor,
    scripted_events: Vec<ExecutionEvent>,
    finish_reason: String,
}

impl FakeBackend {
    fn new(mut events: Vec<ExecutionEvent>, finish_reason: &str) -> Self {
        let has_terminal = events.iter().any(|e| {
            matches!(e, ExecutionEvent::Completed { .. } | ExecutionEvent::Error { .. })
        });
        if !has_terminal {
            // Derive a request_id from the last streaming event if available
            let rid = events
                .iter()
                .find_map(|e| match e {
                    ExecutionEvent::TextDelta { request_id, .. } => Some(*request_id),
                    ExecutionEvent::ReasoningDelta { request_id, .. } => Some(*request_id),
                    _ => None,
                })
                .unwrap_or_else(RequestId::new);

            events.push(ExecutionEvent::Completed {
                request_id: rid,
                result: ExecutionResult {
                    request_id: rid,
                    usage: ModelUsage::default(),
                    cost: harness_protocol::usage::Cost::default(),
                    finish_reason: finish_reason.into(),
                },
            });
        }
        Self {
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "fake-backend".into(),
                description: "Deterministic fake backend for integration tests".into(),
                capabilities: BackendCapabilities {
                    streaming: true,
                    tool_calls: false,
                    ..Default::default()
                },
            },
            scripted_events: events,
            finish_reason: finish_reason.into(),
        }
    }
}

#[async_trait]
impl ExecutionBackend for FakeBackend {
    fn descriptor(&self) -> BackendDescriptor {
        self.descriptor.clone()
    }

    fn capabilities(&self) -> BackendCapabilities {
        self.descriptor.capabilities
    }

    async fn execute(
        &self,
        request: ExecutionRequest,
        events_tx: mpsc::Sender<ExecutionEvent>,
    ) -> Result<ExecutionResult, ExecutionError> {
        for event in &self.scripted_events {
            if events_tx.send(event.clone()).await.is_err() {
                break;
            }
        }
        Ok(ExecutionResult {
            request_id: request.request_id,
            usage: ModelUsage::default(),
            cost: harness_protocol::usage::Cost::default(),
            finish_reason: self.finish_reason.clone(),
        })
    }
}

