// ---------------------------------------------------------------------------
// Integration test — spec §71 Phase 2 goal
// ---------------------------------------------------------------------------

#[tokio::test]
async fn harness_builds_session_sends_prompt_and_receives_events() {
    // ── Arrange ──────────────────────────────────────────────────────────

    // Script a fake backend to emit a single text delta (it auto-appends Completed)
    let request_id = RequestId::new();
    let fake_backend = FakeBackend::new(
        vec![ExecutionEvent::TextDelta {
            request_id,
            delta: "Hello from fake backend!".into(),
        }],
        "end_turn",
    );

    let toolset = fake_toolset();

    // ── Act ──────────────────────────────────────────────────────────────
    //
    // Build a session via the exact builder chain from spec §12 / §63:
    //
    //   harness.session().backend(fake_backend).tools(fake_toolset).start().await?
    //
    // returning a SessionHandle wrapping LocalSessionClient.

    let harness = Harness::new();
    let session = harness
        .session()
        .backend(Arc::new(fake_backend))
        .tools(toolset)
        .start()
        .await
        .expect("SessionBuilder::start() should succeed — spec §63");

    // Subscribe to events before sending the prompt so we don't miss anything
    let mut events = session.subscribe();

    // Send a prompt — this is the "session.send(prompt)" part of the Phase 2 goal
    session
        .send(SessionCommand::Prompt(UserInput {
            text: "Test prompt for integration test".into(),
            attachments: vec![],
        }))
        .await
        .expect("SessionHandle::send() should succeed — spec §76");

    // ── Assert ───────────────────────────────────────────────────────────
    //
    // Phase 2 goal (spec §71) verbatim:
    //   "session.send(prompt) / session.subscribe() works end-to-end
    //    against a fake backend"
    //
    // We verify by collecting events from the subscription and asserting
    // that the expected lifecycle events appear in order.

    let mut session_started = false;
    let mut got_assistant_delta = false;
    let mut got_completed = false;

    while let Ok(Some(event)) = timeout(Duration::from_secs(5), events.recv()).await {
        match event {
            SessionEvent::SessionStarted => {
                session_started = true;
            }
            SessionEvent::Agent { event: env } => {
                match env.event {
                    harness_protocol::events::AgentEvent::AssistantTextDelta { delta, .. } => {
                        got_assistant_delta = true;
                        assert_eq!(
                            delta, "Hello from fake backend!",
                            "AssistantTextDelta should carry the scripted text"
                        );
                    }
                    _ => {}
                }
            }
            SessionEvent::Completed => {
                got_completed = true;
                break;
            }
            _ => {}
        }
    }

    assert!(
        session_started,
        "SessionStarted must be emitted — session.send(prompt) / session.subscribe() \
         works end-to-end (spec §71 Phase 2 goal)"
    );
    assert!(
        got_assistant_delta,
        "AssistantTextDelta must be emitted from fake backend events — \
         session.send(prompt) / session.subscribe() works end-to-end \
         (spec §71 Phase 2 goal)"
    );
    assert!(
        got_completed,
        "Completed must be emitted after backend finishes — \
         session.send(prompt) / session.subscribe() works end-to-end \
         (spec §71 Phase 2 goal)"
    );
}

