    // -----------------------------------------------------------------------

    /// A freshly created agent produces a snapshot with `Idle` status,
    /// `None` current operation, a valid backend descriptor, and zero
    /// usage metrics.
    #[test]
    fn agent_snapshot_from_fresh_agent() {
        let agent = Agent::new(
            AgentId::new(),
            SessionId::new(),
            None,
            "You are a helpful assistant.".into(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: "test-backend".into(),
                    description: "A test backend".into(),
                    capabilities: BackendCapabilities::default(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: HashMap::new(),
                },
                can_spawn_agents: false,
                max_child_depth: None,
                workspace: WorkspaceCapabilities {
                    can_read: false,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        let snap = AgentSnapshot::from_agent(&agent);

        assert_eq!(snap.id, agent.id);
        assert_eq!(snap.parent_id, None);
        assert_eq!(snap.status, AgentStatus::Idle);
        assert!(snap.current_operation.is_none());

        // Backend descriptor is preserved
        assert_eq!(snap.backend.name, "test-backend");

        // Fresh agent has no usage records
        assert_eq!(snap.usage.metrics.total_runs, 0);
        assert_eq!(snap.usage.metrics.total_requests, 0);
        assert!(snap.usage.metrics.total_tokens.is_unknown());
        assert!(snap.usage.metrics.total_cost.is_none());

        // Timestamp is a non-empty RFC 3339 string
        assert!(!snap.usage.timestamp.is_empty(), "timestamp should not be empty");
        assert!(
            snap.usage.timestamp.contains('T'),
            "timestamp should contain 'T' separator: {}",
            snap.usage.timestamp
        );
    }

