        );

        // Push a couple of usage records to the agent's ledger
        agent.usage.records.push(harness_protocol::usage::UsageRecord {
            model_usage: harness_protocol::usage::ModelUsage {
                input_tokens: UsageValue::new(Some(10)),
                output_tokens: UsageValue::new(Some(20)),
                ..Default::default()
            },
            cost: harness_protocol::usage::Cost {
                amount_usd: Some(rust_decimal::Decimal::new(5, 4)), // 0.0005
                source: None,
            },
            tool_usage: None,
        });

        agent.usage.records.push(harness_protocol::usage::UsageRecord {
            model_usage: harness_protocol::usage::ModelUsage {
                input_tokens: UsageValue::new(Some(30)),
                output_tokens: UsageValue::new(Some(40)),
                ..Default::default()
            },
            cost: harness_protocol::usage::Cost {
                amount_usd: Some(rust_decimal::Decimal::new(10, 4)), // 0.0010
                source: None,
