//! Hierarchical cancellation for agent runs (spec §35).
//!
//! Tokio's [`CancellationToken`] forms the backbone — we wrap it in a
//! [`RunCancellation`] scoped to a single agent run.  Child tokens are
//! derived for each backend call, tool call, or child agent spawned
//! during the run.  Cancelling the root propagates to all children
//! automatically.
//!
//! # Hierarchy
//!
//! ```text
//! Session token
//!   └── Agent run token (RunCancellation)
//!         ├── Backend call token
//!         ├── Tool call token
//!         └── Child agent token
//! ```
//!
//! When the run token is cancelled, all child tokens are immediately
//! cancelled, causing in-flight backend streams, tool executors, and
//! child agents to cease work (spec §35: "backend streams, tools,
//! processes").
//!
//! # Session-level integration
//!
//! The session runtime creates a [`CancellationToken`] per session that is
//! wired into the [`AgentTask`](crate::agent_runner::AgentTask) mailbox.
//! When the session receives a [`CancelRun`](crate::runtime::SessionCommand::CancelRun)
//! or [`CancelAgent`](crate::runtime::SessionCommand::CancelAgent) command,
//! the run-loop translates it into [`AgentCommand::Cancel`](harness_protocol::commands::AgentCommand::Cancel),
//! which flows through the agent state machine and triggers the
//! [`RunCancellation`] inside the runner.  The session also cancels its
//! own token as a safety net so that any in-flight backend or tool calls
//! are aborted immediately.

use tokio_util::sync::CancellationToken;

/// A hierarchical cancellation scope for a single agent run.
///
/// Create one per call to [`AgentRunner::run`] or per
/// [`AgentCommand::StartRun`].  The root token is used in the
/// runner's `tokio::select!` loop; child tokens are given to
/// every spawned backend or tool execution so that cancelling the
/// run automatically stops all in-flight work.
///
/// # Session-level usage
///
/// A session can create a [`RunCancellation`] that is a child of the
/// session's own [`CancellationToken`] via [`child_of`](Self::child_of).
/// This lets the session cancel all agent runs when it shuts down,
/// while still allowing individual agent runs to be cancelled
/// independently.
///
/// # Examples
///
/// ```ignore
/// use harness_runtime::cancellation::RunCancellation;
///
/// let run = RunCancellation::new();
///
/// // Hand a child token to a backend call
/// let backend_handle = run.child_token();
/// tokio::spawn(async move { backend.execute(..., backend_handle).await });
///
/// // Cancel the run — the backend task will receive cancellation
/// run.cancel();
/// ```
#[derive(Debug, Clone)]
pub struct RunCancellation {
    /// The root token for this run.  Cancelling it propagates to
    /// every child token created via [`child_token`](Self::child_token).
    root: CancellationToken,
}

impl RunCancellation {
    /// Create a new, un-cancelled run cancellation scope.
    pub fn new() -> Self {
        Self {
            root: CancellationToken::new(),
        }
    }

    /// Create a [`RunCancellation`] that is a child of the given parent
    /// [`CancellationToken`].
    ///
    /// When the parent token is cancelled, this run cancellation is also
    /// cancelled (and vice versa: cancelling this scope does **not**
    /// cancel the parent).
    ///
    /// This is useful for session-level orchestration: the session passes
    /// its own token as the parent so that shutting down the session
    /// propagates to all active agent runs.
    pub fn child_of(parent: &CancellationToken) -> Self {
        Self {
            root: parent.child_token(),
        }
    }

    /// Derive a new child token for a backend or tool execution.
    ///
    /// Multiple calls return independent child tokens.  Cancelling
    /// any one of them does **not** affect the root or other children;
    /// cancelling the root cancels all children.
    pub fn child_token(&self) -> CancellationToken {
        self.root.child_token()
    }

    /// Cancel the entire run.
    ///
    /// All existing child tokens (backend, tool, child agent) are
    /// immediately cancelled.  New child tokens created after this
    /// call will also start in the cancelled state.
    pub fn cancel(&self) {
        self.root.cancel();
    }

    /// Returns `true` if the run (or any ancestor) has been cancelled.
    pub fn is_cancelled(&self) -> bool {
        self.root.is_cancelled()
    }

    /// Returns a clone of the root token, suitable for use in the
    /// runner's `tokio::select!` loop to detect cancellation.
    pub fn token(&self) -> CancellationToken {
        self.root.clone()
    }
}

impl Default for RunCancellation {
    fn default() -> Self {
        Self::new()
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    /// A fresh `RunCancellation` is not cancelled.
    #[test]
    fn not_cancelled_by_default() {
        let run = RunCancellation::new();
        assert!(!run.is_cancelled());
    }

    /// Cancelling the root marks it as cancelled.
    #[test]
    fn cancel_marks_cancelled() {
        let run = RunCancellation::new();
        run.cancel();
        assert!(run.is_cancelled());
    }

    /// Child tokens share the cancellation state of the root.
    #[test]
    fn child_token_inherits_cancellation() {
        let run = RunCancellation::new();
        let child = run.child_token();
        assert!(!child.is_cancelled());

        run.cancel();
        assert!(child.is_cancelled());
    }

    /// Multiple child tokens are all cancelled when the root is cancelled.
    #[test]
    fn multiple_children_all_cancelled() {
        let run = RunCancellation::new();
        let c1 = run.child_token();
        let c2 = run.child_token();

        run.cancel();
        assert!(c1.is_cancelled());
        assert!(c2.is_cancelled());
    }

    /// Cloning `RunCancellation` shares the same root token.
    #[test]
    fn clone_shares_root() {
        let run_a = RunCancellation::new();
        let run_b = run_a.clone();

        run_a.cancel();
        assert!(run_b.is_cancelled());
    }

    /// New children created after cancellation are already cancelled.
    #[test]
    fn child_token_after_cancel_is_cancelled() {
        let run = RunCancellation::new();
        run.cancel();
        let child = run.child_token();
        assert!(child.is_cancelled());
    }

    /// `child_of` creates a scope that inherits from the parent token.
    #[test]
    fn child_of_inherits_parent_cancellation() {
        let parent = CancellationToken::new();
        let run = RunCancellation::child_of(&parent);
        assert!(!run.is_cancelled());

        parent.cancel();
        assert!(run.is_cancelled());
    }

    /// `child_of` does not propagate cancellation to the parent when the
    /// child scope is cancelled.
    #[test]
    fn child_of_does_not_cancel_parent() {
        let parent = CancellationToken::new();
        let run = RunCancellation::child_of(&parent);
        assert!(!parent.is_cancelled());

        run.cancel();
        // The parent should remain un-cancelled.
        assert!(!parent.is_cancelled());
        // The child scope itself is cancelled.
        assert!(run.is_cancelled());
    }
}

//! A scripted test-double backend that replays predetermined [`ExecutionEvent`]s
//! and returns a configured [`ExecutionResult`] or [`ExecutionError`].
//!
//! Use [`FakeBackend`] in unit tests and integration tests to exercise agent
//! runners, session logic, and tool orchestration without making real API calls.

use async_trait::async_trait;
use tokio_util::sync::CancellationToken;

use harness_protocol::backend::{
    BackendCapabilities, BackendDescriptor, ExecutionContext, ExecutionError, ExecutionEvent,
    ExecutionRequest, ExecutionResult,
};
use harness_protocol::ids::BackendId;

use crate::traits::{ExecutionBackend, ExecutionEventSink};

/// A test-double [`ExecutionBackend`] that replays a scripted sequence of
/// [`ExecutionEvent`]s through the provided [`ExecutionEventSink`] and then
/// returns a predetermined [`ExecutionResult`] or [`ExecutionError`].
///
/// The backend respects the [`CancellationToken`]: if cancellation is
/// signalled at any point during event streaming, execution stops
/// immediately and returns [`ExecutionError::Cancelled`].
///
/// # Example
///
/// ```ignore
/// use harness_runtime::testing::fake_backend::FakeBackend;
/// use harness_protocol::backend::*;
/// use harness_protocol::ids::RequestId;
/// use harness_protocol::usage::{Cost, ModelUsage};
///
/// let request_id = RequestId::new();
/// let events = vec![
///     ExecutionEvent::TextDelta { request_id, delta: "Hello ".into() },
///     ExecutionEvent::TextDelta { request_id, delta: "world!".into() },
/// ];
///
/// let result = ExecutionResult {
///     request_id,
///     usage: ModelUsage::default(),
///     cost: Cost::default(),
///     finish_reason: "end_turn".into(),
/// };
///
/// let backend = FakeBackend::new(events, Ok(result));
/// ```
#[derive(Debug)]
pub struct FakeBackend {
    /// The sequence of [`ExecutionEvent`]s streamed during [`execute`](ExecutionBackend::execute).
    pub scripted_events: Vec<ExecutionEvent>,
    /// The outcome returned after all scripted events have been sent.
    pub outcome: Result<ExecutionResult, ExecutionError>,
}

impl FakeBackend {
    /// Creates a new `FakeBackend` that will stream `scripted_events` through
    /// the event sink and then return `outcome`.
    ///
    /// # Arguments
    ///
    /// * `scripted_events` — Events to emit in order during execution.
    /// * `outcome` — The final `Ok(ExecutionResult)` or `Err(ExecutionError)`
    ///   returned once all events have been sent (or execution is cancelled).
    pub fn new(
        scripted_events: Vec<ExecutionEvent>,
        outcome: Result<ExecutionResult, ExecutionError>,
    ) -> Self {
        Self {
            scripted_events,
            outcome,
        }
    }
}

#[async_trait]
impl ExecutionBackend for FakeBackend {
    fn descriptor(&self) -> BackendDescriptor {
        BackendDescriptor {
            id: BackendId::new(),
            name: "fake".into(),
            description: "A test-double backend that replays scripted events.".into(),
            capabilities: BackendCapabilities {
                streaming: true,
                ..Default::default()
            },
        }
    }

    fn capabilities(&self) -> BackendCapabilities {
        let desc = self.descriptor();
        desc.capabilities
    }

    async fn execute(
        &self,
        _request: ExecutionRequest,
        _context: ExecutionContext,
        events: ExecutionEventSink,
        cancel: CancellationToken,
    ) -> Result<ExecutionResult, ExecutionError> {
        // Stream all scripted events, checking cancellation before each one.
        for event in &self.scripted_events {
            if cancel.is_cancelled() {
                // Drop the sender so the consumer sees the channel close.
                drop(events);
                return Err(ExecutionError::Cancelled);
            }

            // If the receiver has been dropped, treat it as cancellation.
            if events.send(event.clone()).is_err() {
                return Err(ExecutionError::Cancelled);
            }
        }

        // One last cancellation check before returning the outcome.
        if cancel.is_cancelled() {
            drop(events);
            return Err(ExecutionError::Cancelled);
        }

        self.outcome.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use harness_protocol::ids::RequestId;
    use harness_protocol::usage::{Cost, ModelUsage};

    #[tokio::test]
    async fn streams_all_events_and_returns_ok() {
        let request_id = RequestId::new();
        let events = vec![
            ExecutionEvent::TextDelta {
                request_id,
                delta: "step one ".into(),
            },
            ExecutionEvent::TextDelta {
                request_id,
                delta: "step two".into(),
            },
        ];
        let result = ExecutionResult {
            request_id,
            usage: ModelUsage::default(),
            cost: Cost::default(),
            finish_reason: "end_turn".into(),
        };

        let backend = FakeBackend::new(events.clone(), Ok(result.clone()));

        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let cancel = CancellationToken::new();

        // Spawn execution on a separate task since execute is async.
        let handle = {
            let backend = backend;
            let request = ExecutionRequest {
                request_id,
                run_id: harness_protocol::ids::RunId::new(),
                system_prompt: String::new(),
                messages: vec![],
                tools: vec![],
                extended_thinking: false,
            };
            let context = ExecutionContext {
                max_tokens: None,
                temperature: None,
                stop_sequences: vec![],
            };
            tokio::spawn(async move {
                backend.execute(request, context, tx, cancel).await
            })
        };

        // Collect all streamed events.
        let mut received = Vec::new();
        while let Some(event) = rx.recv().await {
            received.push(event);
        }

        // Await the execution result.
        let outcome = handle.await.expect("task panicked");

        assert_eq!(received.len(), 2);
        assert_eq!(outcome, Ok(result));
    }

    #[tokio::test]
    async fn returns_error_outcome() {
        let request_id = RequestId::new();
        let backend = FakeBackend::new(vec![], Err(ExecutionError::Timeout));

        let (tx, rx) = tokio::sync::mpsc::unbounded_channel();
        let cancel = CancellationToken::new();

        let result = backend
            .execute(
                ExecutionRequest {
                    request_id,
                    run_id: harness_protocol::ids::RunId::new(),
                    system_prompt: String::new(),
                    messages: vec![],
                    tools: vec![],
                    extended_thinking: false,
                },
                ExecutionContext {
                    max_tokens: None,
                    temperature: None,
                    stop_sequences: vec![],
                },
                tx,
                cancel,
            )
            .await;

        // Drop receiver so the channel closes cleanly.
        drop(rx);

        assert_eq!(result, Err(ExecutionError::Timeout));
    }

    #[tokio::test]
    async fn cancellation_stops_mid_script() {
        let request_id = RequestId::new();
        let events = vec![
            ExecutionEvent::TextDelta {
                request_id,
                delta: "before ".into(),
            },
            ExecutionEvent::TextDelta {
                request_id,
                delta: "after".into(),
            },
        ];
        let result = ExecutionResult {
            request_id,
            usage: ModelUsage::default(),
            cost: Cost::default(),
            finish_reason: "end_turn".into(),
        };

        let backend = FakeBackend::new(events.clone(), Ok(result));

        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let cancel = CancellationToken::new();

        let handle = {
            let backend = backend;
            let request = ExecutionRequest {
                request_id,
                run_id: harness_protocol::ids::RunId::new(),
                system_prompt: String::new(),
                messages: vec![],
                tools: vec![],
                extended_thinking: false,
            };
            let context = ExecutionContext {
                max_tokens: None,
                temperature: None,
                stop_sequences: vec![],
            };
            tokio::spawn(async move {
                backend.execute(request, context, tx, cancel).await
            })
        };

        // Receive first event, then cancel.
        let first = rx.recv().await;
        assert!(first.is_some());
        cancel.cancel();

        // The execution should now return Cancelled.
        let outcome = handle.await.expect("task panicked");
        assert_eq!(outcome, Err(ExecutionError::Cancelled));

        // The second event should NOT have been sent; receiver is closed.
        let remaining = rx.recv().await;
        assert!(remaining.is_none(), "expected no more events after cancellation");
    }
}
